-- ============================================================================
-- Language catalog → Supabase
--
-- GENERATED FILE — edit lib/languages.ts (or a lib/*-plus.ts bank) and run
-- `npm run catalog:sql`. Hand edits here are lost on the next build.
--
-- Run once in the Supabase dashboard → SQL editor, after schema.sql:
-- https://supabase.com/dashboard/project/rlulmewvmhxgctonizas/sql
--
-- Safe to re-run: the DDL is idempotent and the seed uses ON CONFLICT DO NOTHING,
-- so a lesson edited in the dashboard is never overwritten by a later run.
--
-- After this runs, the app reads lesson title/theory/questions from these tables
-- through lib/languageCatalog.ts. The bundled catalog stays as the offline and
-- first-run fallback. Editing a row changes the lesson on the next launch (the
-- loader caches for five minutes); no app release is needed.
--
-- 86 lessons · 6 courses.
-- ============================================================================

create table if not exists public.language_courses (
  id text primary key,
  title text not null,
  icon text not null default '',
  blurb text not null default '',
  position integer not null default 0,
  published boolean not null default true,
  updated_at timestamptz not null default now()
);

create table if not exists public.language_lessons (
  id text primary key,
  course_id text not null references public.language_courses (id) on delete cascade,
  title text not null,
  theory jsonb not null default '[]'::jsonb,
  questions jsonb not null default '[]'::jsonb,
  position integer not null default 0,
  published boolean not null default true,
  updated_at timestamptz not null default now(),
  constraint language_lessons_theory_is_array check (jsonb_typeof(theory) = 'array'),
  constraint language_lessons_questions_is_array check (jsonb_typeof(questions) = 'array')
);

create index if not exists language_lessons_course_position
  on public.language_lessons (course_id, position);

create or replace function public.touch_language_catalog()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists language_courses_touch on public.language_courses;
create trigger language_courses_touch
  before update on public.language_courses
  for each row execute function public.touch_language_catalog();

drop trigger if exists language_lessons_touch on public.language_lessons;
create trigger language_lessons_touch
  before update on public.language_lessons
  for each row execute function public.touch_language_catalog();

alter table public.language_courses enable row level security;
alter table public.language_lessons enable row level security;

-- Public read, dashboard/service-role write. Unpublishing a row hides it from
-- the app immediately; the bundled lesson remains as the offline fallback.
drop policy if exists "Anyone can read published language courses" on public.language_courses;
create policy "Anyone can read published language courses"
  on public.language_courses for select using (published);

drop policy if exists "Anyone can read published language lessons" on public.language_lessons;
create policy "Anyone can read published language lessons"
  on public.language_lessons for select using (published);

grant select on public.language_courses, public.language_lessons to anon, authenticated;
grant select on public.language_courses, public.language_lessons to service_role;
grant insert, update, delete on public.language_courses, public.language_lessons to service_role;

comment on table public.language_courses is
  'Language course metadata. Managed in Supabase; read by the app via lib/languageCatalog.ts.';
comment on table public.language_lessons is
  'Lesson content: theory (jsonb string[]) and questions (jsonb CourseQuestion[]). Edits apply without an app release.';

-- Seed: ON CONFLICT DO NOTHING so dashboard edits survive re-runs.
insert into public.language_courses (id, title, icon, blurb, position, published)
select x.id, x.title, x.icon, x.blurb, x.position, true
from jsonb_to_recordset($catalog_courses$[
  {"id":"spanish","title":"Spanish","icon":"🇪🇸","blurb":"Hold your first conversations","position":1},
  {"id":"french","title":"French","icon":"🇫🇷","blurb":"Charm your way through Paris","position":2},
  {"id":"german","title":"German","icon":"🇩🇪","blurb":"Order, introduce, and apologise","position":3},
  {"id":"swahili","title":"Swahili","icon":"🇰🇪","blurb":"Karibu — speak with East Africa","position":4},
  {"id":"chess","title":"Chess","icon":"♟️","blurb":"From moves to mating nets","position":5},
  {"id":"english","title":"English","icon":"🇬🇧","blurb":"Master English grammar and conversation","position":6}
]$catalog_courses$::jsonb)
  as x(id text, title text, icon text, blurb text, position integer)
on conflict (id) do nothing;

insert into public.language_lessons (id, course_id, title, theory, questions, position, published)
select x.id, x.course_id, x.title, x.theory, x.questions, x.position, true
from jsonb_to_recordset($catalog_lessons$[
  {"id":"spanish-basics","course_id":"spanish","title":"Spanish Basics","theory":["Spanish is spoken by 500M+ people. Start the Duolingo way: greetings first — Hola (hello), Adiós (goodbye), Gracias (thank you), Por favor (please).","Every Spanish noun has gender: el for masculine, la for feminine. Niña (girl) is feminine → la niña."],"questions":[{"prompt":"How do you say \"Hello\" in Spanish?","correctChain":["Hola"],"scrambledTokens":["Hola","Adiós","Gracias","Por favor"],"explain":"Hola opens every conversation — nail it first."},{"prompt":"\"Gracias\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Goodbye","Welcome"],"explain":"Gratitude unlocks kindness in every language."},{"prompt":"Say \"I eat apples\":","correctChain":["Yo","como","manzanas"],"scrambledTokens":["manzanas","Yo","el","como"],"explain":"Yo = I, como = (I) eat from comer, manzanas = apples."},{"prompt":"Which article goes with \"niña\" (girl)?","correctChain":["la"],"scrambledTokens":["la","el","los","un"],"explain":"Feminine nouns take la; masculine nouns take el."},{"prompt":"Say goodbye to a friend:","correctChain":["Adiós","amigo"],"scrambledTokens":["amigo","Hola","Adiós","gracias"],"explain":"Adiós = goodbye, amigo = friend."}],"position":1},
  {"id":"spanish-phrases","course_id":"spanish","title":"Spanish Phrases","theory":["Move past single words: ask how people are (¿Cómo estás?), introduce yourself (Me llamo…), and soften every request with Por favor.","Gratitude scales up: Gracias → Muchas gracias (thank you very much). Goodbyes scale too: Adiós → Hasta luego (see you later)."],"questions":[{"prompt":"\"¿Cómo estás?\" means…","correctChain":["How are you?"],"scrambledTokens":["How are you?","What is your name?","Where are you from?","How old are you?"],"explain":"The go-to greeting right after Hola."},{"prompt":"Say \"My name is Ana\":","correctChain":["Me","llamo","Ana"],"scrambledTokens":["Ana","Yo","Me","llamo"],"explain":"Me llamo = I call myself — the Spanish introduction."},{"prompt":"\"Por favor\" means…","correctChain":["Please"],"scrambledTokens":["Please","Thank you","Sorry","Welcome"],"explain":"Por favor softens every request."},{"prompt":"Say \"Thank you very much\":","correctChain":["Muchas","gracias"],"scrambledTokens":["gracias","Hola","Muchas","por"],"explain":"Muchas = many; gracias = thanks. Stack them for emphasis."},{"prompt":"\"Hasta luego\" means…","correctChain":["See you later"],"scrambledTokens":["See you later","Good night","Good luck","Welcome back"],"explain":"Hasta = until; luego = later. Warmer than Adiós."}],"position":2},
  {"id":"spanish-tenses","course_id":"spanish","title":"Spanish Tenses Lab","theory":["Present tense runs on endings: -o = I (hablo), -as = you (hablas), -a = he/she (habla), -amos = we (hablamos), -an = they (hablan).","Ser vs estar: ser for identity, events and time (la fiesta es hoy); estar for location and mood (estoy cansado)."],"questions":[{"prompt":"\"___ hablo español.\" (I speak Spanish.)","correctChain":["Yo"],"scrambledTokens":["Yo","Tú","Él","Ellos"],"explain":"The verb ends in -o → the speaker is “I”: Yo hablo."},{"prompt":"Say \"We speak English\":","correctChain":["Nosotros","hablamos","inglés"],"scrambledTokens":["inglés","Nosotros","hablamos","hablas"],"explain":"-amos = we: hablamos. Spanish often drops the pronoun!"},{"prompt":"\"La fiesta ___ hoy.\" (The party is today.)","correctChain":["es"],"scrambledTokens":["es","está","son","están"],"explain":"Ser for events and time: la fiesta es hoy."},{"prompt":"Ask \"Where is the bathroom?\":","correctChain":["Dónde","está","el","baño"],"scrambledTokens":["baño","Dónde","el","está","es"],"explain":"Location of things uses estar: ¿dónde está…?"},{"prompt":"\"Ellos ___ tacos.\" (They eat tacos.)","correctChain":["comen"],"scrambledTokens":["como","comes","come","comen"],"explain":"-er verbs: ellos take -en → comen."}],"position":3},
  {"id":"spanish-quiz","course_id":"spanish","title":"Spanish Checkpoint","theory":["Checkpoint: greetings, phrases, gender, and tenses from the full Spanish course."],"questions":[{"prompt":"How do you say \"Hello\" in Spanish?","correctChain":["Hola"],"scrambledTokens":["Hola","Adiós","Gracias","Por favor"],"explain":"Hola opens every conversation."},{"prompt":"Say \"I eat apples\":","correctChain":["Yo","como","manzanas"],"scrambledTokens":["manzanas","Yo","el","como"],"explain":"Yo = I, como = (I) eat, manzanas = apples."},{"prompt":"Which article goes with \"libro\" (book)?","correctChain":["el"],"scrambledTokens":["el","la","los","las"],"explain":"Libro is masculine → el. La niña, el libro."},{"prompt":"Say \"My name is Ana\":","correctChain":["Me","llamo","Ana"],"scrambledTokens":["Ana","Me","llamo","Tú"],"explain":"Me llamo Ana — introduce yourself anywhere."},{"prompt":"\"¿Cómo estás?\" means…","correctChain":["How are you?"],"scrambledTokens":["How are you?","What is your name?","Where are you?","How old are you?"],"explain":"Ask it after Hola to start a real conversation."},{"prompt":"\"Ellos ___ tacos.\" (They eat tacos.)","correctChain":["comen"],"scrambledTokens":["como","comes","come","comen"],"explain":"Tenses check: ellos take -en → comen."}],"position":4},
  {"id":"spanish-greetings","course_id":"spanish","title":"Spanish Greetings & Politeness","theory":["Hola opens everything; Buenos días (morning), Buenas tardes (afternoon), Buenas noches (night)Ride the clock. ¿Cómo estás? asks a friend, ¿Cómo está usted? respects an elder — tú for friends, usted for respect.","Always land with por favor, gracias, and perdón. De nada answers gracias; ¡Bienvenidos! welcomes everyone."],"questions":[{"prompt":"“Buenas noches” is said…","correctChain":["At night"],"scrambledTokens":["At night","In the morning","At noon","At farewell only"],"explain":"Noches = night. Tardes = afternoon, días = morning."},{"prompt":"Ask a friend “How are you?”:","correctChain":["Cómo","estás"],"scrambledTokens":["estás","Cómo","está","estoy"],"explain":"¿Cómo estás? — tú form, friends and family."},{"prompt":"“¿Cómo está usted?” differs from “¿Cómo estás?” in…","correctChain":["Formality"],"scrambledTokens":["Formality","Tense","Number","Meaning"],"explain":"Usted = respect (elders, officials). Tú = friends."},{"prompt":"Answer “thanks” with “you are welcome”:","correctChain":["De","nada"],"scrambledTokens":["nada","De","Gracias","Favor"],"explain":"Gracias → De nada. A tiny perfect pair."},{"prompt":"“¡Bienvenidos!” means…","correctChain":["Welcome! (to everyone)"],"scrambledTokens":["Welcome! (to everyone)","Goodbye!","Congratulations!","Good luck!"],"explain":"Bienvenido (one man), bienvenida (one woman), bienvenidos (all)."}],"position":5},
  {"id":"spanish-numbers-time","course_id":"spanish","title":"Spanish Numbers & Time","theory":["Count: uno, dos, tres, cuatro, cinco, seis, siete, ocho, nueve, diez — then veinte, treinta… cien. Son las tres = it is 3 o’clock; Es la una = it is 1 o’clock (only one is singular!).","Days run lunes to domingo; months enero to diciembre. Hoy = today, mañana = tomorrow, ayer = yesterday."],"questions":[{"prompt":"“Siete” means…","correctChain":["Seven"],"scrambledTokens":["Seven","Six","Eight","Ten"],"explain":"Seis 6, siete 7, ocho 8 — chant the run."},{"prompt":"Say “It is 3 o’clock”:","correctChain":["Son","las","tres"],"scrambledTokens":["tres","Son","Es","las"],"explain":"Plural hours take Son las; only 1 o’clock takes Es la una."},{"prompt":"“Mañana” means…","correctChain":["Tomorrow"],"scrambledTokens":["Tomorrow","Morning","Yesterday","Today"],"explain":"Mañana does double duty: tomorrow AND morning. Context decides."},{"prompt":"Say “ten” (10):","correctChain":["Diez"],"scrambledTokens":["Nueve","Diez","Once","Doce"],"explain":"Nueve 9, diez 10, once 11, doce 12."},{"prompt":"“Es la una” is used because…","correctChain":["One o’clock is singular"],"scrambledTokens":["One o’clock is singular","Nights are singular","Una is formal","It is a question"],"explain":"La una = the one (hour). Every other hour is las."}],"position":6},
  {"id":"spanish-food","course_id":"spanish","title":"Spanish Food & Drink","theory":["Order like a local: Quiero… (I want…), La cuenta, por favor (the bill, please). El agua, el pan, el café, la leche, el arroz, el pollo, la fruta — hunger solved.","Tengo hambre = I am hungry (I HAVE hunger), tengo sed = I am thirsty. Me gusta = I like it; me encanta = I love it."],"questions":[{"prompt":"“El pollo” means…","correctChain":["The chicken"],"scrambledTokens":["The chicken","The fish","The bread","The rice"],"explain":"Pollo = chicken, pescado = fish, pan = bread."},{"prompt":"Say “I want coffee”:","correctChain":["Quiero","café"],"scrambledTokens":["café","Quiero","Tengo","Agua"],"explain":"Quiero + anything: quiero agua, quiero la cuenta."},{"prompt":"“Tengo hambre” literally means…","correctChain":["I have hunger"],"scrambledTokens":["I have hunger","I eat hunger","I am hunger","My hunger eats"],"explain":"Spanish HAS hunger and thirst: tengo hambre, tengo sed."},{"prompt":"Ask for the bill politely:","correctChain":["La","cuenta"],"scrambledTokens":["cuenta","La","Quiero","Menú"],"explain":"La cuenta, por favor — the magic exit words."},{"prompt":"“Me encanta” means…","correctChain":["I love it"],"scrambledTokens":["I love it","I hate it","I want it","I need it"],"explain":"Gusta = like, encanta = love. Me encanta el café!"}],"position":7},
  {"id":"spanish-travel","course_id":"spanish","title":"Spanish Travel & Directions","theory":["Move with confidence: ¿Dónde está…? (where is…?), a la izquierda (left), a la derecha (right), todo recto (straight). La estación, el aeropuerto, el hotel, el baño — the big four.","Ride anything: el autobús, el tren, el taxi. ¿Cuánto cuesta? (how much?), ¿A qué hora sale? (what time does it leave?)."],"questions":[{"prompt":"“¿Dónde está el baño?” asks for…","correctChain":["The bathroom’s location"],"scrambledTokens":["The bathroom’s location","The bath’s price","Bath time","A bad room"],"explain":"Dónde = where. Dónde está…? unlocks every city."},{"prompt":"Say “to the left”:","correctChain":["A","la","izquierda"],"scrambledTokens":["izquierda","A","derecha","la"],"explain":"Izquierda = left, derecha = right. Todo recto = straight on."},{"prompt":"“¿A qué hora sale?” asks for…","correctChain":["The departure time"],"scrambledTokens":["The departure time","The ticket price","The platform","The arrival"],"explain":"Salir = to leave. ¿A qué hora…? pins any schedule."},{"prompt":"Ask “How much does it cost?”:","correctChain":["Cuánto","cuesta"],"scrambledTokens":["cuesta","Cuánto","Cuesta","Cuestan"],"explain":"¿Cuánto cuesta? — singular thing. ¿Cuánto cuestan? — many."},{"prompt":"“El tren” means…","correctChain":["The train"],"scrambledTokens":["The train","The bus","The taxi","The plane"],"explain":"Tren = train, autobús = bus, avión = plane."}],"position":8},
  {"id":"spanish-family","course_id":"spanish","title":"Spanish Family & Descriptions","theory":["Meet la familia: la madre, el padre, el hermano, la hermana, el hijo, la hija, el amigo. Mi/mis = my, tu/tus = your, su/sus = his/her/their.","Describe with ser + adjective, matching gender and number: alto/alta, altos/altas; pequeño, grande, feliz. Soy alto = I am tall."],"questions":[{"prompt":"“La hermana” means…","correctChain":["The sister"],"scrambledTokens":["The sister","The brother","The mother","The daughter"],"explain":"Hermana = sister, hermano = brother. La familia grows."},{"prompt":"Say “my brothers” (more than one):","correctChain":["Mis","hermanos"],"scrambledTokens":["hermanos","Mi","Mis","Tu"],"explain":"Mi → mis before plurals: mis hermanos, mis amigos."},{"prompt":"“Soy alta” is said by…","correctChain":["A tall woman/girl"],"scrambledTokens":["A tall woman/girl","A tall man","Tall children","Anyone tall"],"explain":"Adjectives agree: -o men, -a women, -os/-as plurals."},{"prompt":"Say “your (friend’s) mother”:","correctChain":["Tu","madre"],"scrambledTokens":["madre","Su","Tu","Mi"],"explain":"Tu = your (friend), su = his/her/their. Madre = mother."},{"prompt":"“El hijo” means…","correctChain":["The son"],"scrambledTokens":["The son","The daughter","The father","The child (neutral)"],"explain":"Hijo = son, hija = daughter, hijos = children/sons."}],"position":9},
  {"id":"spanish-verbs-present","course_id":"spanish","title":"Spanish Present Verbs","theory":["Three endings rule the present: -ar (hablar), -er (comer), -ir (vivir). Hablo, hablas, habla, hablamos, hablan — the endings sing the person.","Must-knows: soy (I am), tengo (I have), quiero (I want), puedo (I can). Estar describes place and mood: estoy en casa, estoy feliz."],"questions":[{"prompt":"Say “I speak Spanish”:","correctChain":["Hablo","español"],"scrambledTokens":["español","Hablo","Hablas","Habla"],"explain":"-ar verbs: hablo (I), hablas (you), habla (he/she)."},{"prompt":"“Comemos” means…","correctChain":["We eat"],"scrambledTokens":["We eat","You eat","They eat","He eats"],"explain":"-er verbs: como, comes, come, comemos, comen."},{"prompt":"Say “I am happy” (feeling → estar):","correctChain":["Estoy","feliz"],"scrambledTokens":["feliz","Soy","Estoy","Estás"],"explain":"Estar = how/where: estoy feliz. Ser = what: soy alto."},{"prompt":"“Puedo” means…","correctChain":["I can"],"scrambledTokens":["I can","I want","I have","I go"],"explain":"Poder → puedo. Querer → quiero. Tener → tengo."},{"prompt":"Say “They live here” (vivir):","correctChain":["Viven","aquí"],"scrambledTokens":["aquí","Viven","Vivo","Vives"],"explain":"-ir verbs: vivo, vives, vive, viven. Aquí = here."}],"position":10},
  {"id":"spanish-past","course_id":"spanish","title":"Spanish Past Stories","theory":["Yesterday speaks in preterite: hablé (I spoke), comí (I ate), viví (I lived). -ar takes -é, -er/-ir take -í — one accent, whole past.","The rebels: fui (I went/was), tuve (I had), hice (I did/made), dije (I said). Ayer = yesterday, la semana pasada = last week."],"questions":[{"prompt":"“Hablé” means…","correctChain":["I spoke"],"scrambledTokens":["I spoke","I speak","I will speak","Speak!"],"explain":"Hablé with the accent = finished past. Hablo = now."},{"prompt":"Say “I ate rice” (comer → comí):","correctChain":["Comí","arroz"],"scrambledTokens":["arroz","Comí","Como","Comer"],"explain":"Comí: -er past takes -í. Arroz = rice."},{"prompt":"“Fui” can mean…","correctChain":["I went / I was"],"scrambledTokens":["I went / I was","I go","I will go","Go!"],"explain":"Ser and ir share fui in the past — context picks."},{"prompt":"Say “last week”:","correctChain":["La","semana","pasada"],"scrambledTokens":["pasada","La","semana","ayer"],"explain":"La semana pasada frames any finished story."},{"prompt":"“Hice” means…","correctChain":["I did / I made"],"scrambledTokens":["I did / I made","I do","I say","I have"],"explain":"Hacer → hice. Dije = I said, tuve = I had."}],"position":11},
  {"id":"spanish-final","course_id":"spanish","title":"Spanish Final Exam","theory":["Final exam: greetings, numbers, food, travel, family, present verbs, and past stories — the whole comprehensive course."],"questions":[{"prompt":"Ask a friend “How are you?”:","correctChain":["Cómo","estás"],"scrambledTokens":["estás","Cómo","está","estoy"],"explain":"Tú form for friends: ¿Cómo estás?"},{"prompt":"“Son las tres” tells…","correctChain":["The time (3 o’clock)"],"scrambledTokens":["The time (3 o’clock)","Three are sons","Three things","Tuesday"],"explain":"Son las + hour. Es la una for 1 o’clock only."},{"prompt":"Say “They live here”:","correctChain":["Viven","aquí"],"scrambledTokens":["aquí","Viven","Vivo","Vivimos"],"explain":"-ir present: viven = they live."},{"prompt":"“Tengo hambre” means…","correctChain":["I am hungry"],"scrambledTokens":["I am hungry","I have ham","I eat bread","I am thirsty"],"explain":"Tengo hambre = I have hunger. Tengo sed = thirsty."},{"prompt":"“Hablé” vs “hablo”: the difference is…","correctChain":["Past vs present"],"scrambledTokens":["Past vs present","Formal vs casual","Loud vs quiet","None"],"explain":"The accent marks the finished past: hablé = I spoke."},{"prompt":"Ask “Where is the station?”:","correctChain":["Dónde","está"],"scrambledTokens":["está","Dónde","Cuánto","Está"],"explain":"¿Dónde está…? + place. La estación = the station."},{"prompt":"You are at a café in Madrid. You want water and the bill. Which pair is most natural?","correctChain":["Un agua, por favor. La cuenta, por favor."],"scrambledTokens":["Un agua, por favor. La cuenta, por favor.","Agua cuenta por favor.","Yo quiero agua y cuenta.","Una agua, la cuenta."],"explain":"Por favor softens both requests, and la cuenta is the bill. Politeness is part of the language, not decoration."},{"kind":"text","prompt":"Type the Spanish for “I don’t understand.”","correctChain":["No entiendo."],"scrambledTokens":[],"explain":"No entiendo and no comprendo both mean “I don’t understand”; entiendo is the most common everyday choice.","text":{"answers":["No entiendo.","No comprendo."],"misconceptions":{"No entiendo nada":"That means “I understand nothing” — stronger than the neutral phrase."}}}],"position":12},
  {"id":"spanish-questions","course_id":"spanish","title":"Spanish Questions & Negation","theory":["Spanish questions carry an opening ¿ and usually put the question word first: ¿Dónde está el baño? (Where is the bathroom?), ¿Cuándo llegas? (When do you arrive?), ¿Por qué estudias español? (Why do you study Spanish?).","A yes/no question can simply rise in pitch: ¿Hablas español? The subject can come before or after the verb — ¿Tú hablas español? and ¿Hablas tú español? both work.","Negation is no before the verb: No hablo francés. Double negatives are normal and emphatic: No veo nada (I see nothing), No hay nadie (there is nobody). Use tú with friends and usted in formal situations."],"questions":[{"prompt":"Which word means “where”?","correctChain":["dónde"],"scrambledTokens":["dónde","cuándo","quién","cómo"],"explain":"Dónde = where, cuándo = when, quién = who, cómo = how."},{"prompt":"Ask “Where is the bathroom?”","correctChain":["Dónde","está","el","baño"],"scrambledTokens":["baño","Dónde","está","el","cuándo"],"explain":"¿Dónde está…? + place. El baño = the bathroom; está = is (location)."},{"prompt":"“No hablo francés” means…","correctChain":["I don’t speak French"],"scrambledTokens":["I don’t speak French","I speak French","I don’t study French","I want to learn French"],"explain":"No before the verb negates the whole sentence: no hablo = I don’t speak."},{"prompt":"Say “I don’t have time”:","correctChain":["No","tengo","tiempo"],"scrambledTokens":["tiempo","No","tengo","tiene"],"explain":"No + tengo + tiempo. Tiene is the usted/él form, not yo."},{"prompt":"“No veo nada” means…","correctChain":["I see nothing"],"scrambledTokens":["I see nothing","I don’t see the water","I see everything","I don’t want to see"],"explain":"Spanish keeps both negatives: no + veo + nada. Literally “I don’t see nothing,” meaning I see nothing."}],"position":13},
  {"id":"spanish-health","course_id":"spanish","title":"Spanish Health & Emergencies","theory":["Say what hurts with doler: Me duele la cabeza (I have a headache), Me duele el estómago (my stomach hurts). For plural body parts use duelen: Me duelen los pies.","Symptoms: Tengo fiebre (I have a fever), Tengo tos (I have a cough). Ask for help with Necesito un médico (I need a doctor), ¿Dónde está la farmacia? (where is the pharmacy?), or Llame a una ambulancia (call an ambulance — formal).","Allergies: Soy alérgico/a a los cacahuetes. Use ¿Puede ayudarme? for a polite “Can you help me?”."],"questions":[{"prompt":"“Me duele la cabeza” means…","correctChain":["I have a headache"],"scrambledTokens":["I have a headache","I have a stomach ache","My feet hurt","I am dizzy"],"explain":"Me duele + singular body part: la cabeza = the head. Duelen is for plural parts."},{"prompt":"Say “I need a doctor”:","correctChain":["Necesito","un","médico"],"scrambledTokens":["médico","Necesito","un","médica"],"explain":"Necesito = I need; un médico = a doctor. Médica is the feminine form of the profession."},{"prompt":"“Tengo fiebre” means…","correctChain":["I have a fever"],"scrambledTokens":["I have a fever","I have a cough","I am cold","I have a headache"],"explain":"Tener + fiebre = to have a fever. Tos is a cough."},{"prompt":"Ask “Where is the pharmacy?”","correctChain":["Dónde","está","la","farmacia"],"scrambledTokens":["farmacia","Dónde","está","la","el"],"explain":"¿Dónde está la farmacia? — farmacia is feminine, so la farmacia."},{"prompt":"“Soy alérgico a los cacahuetes” means…","correctChain":["Peanuts make me ill"],"scrambledTokens":["Peanuts make me ill","I love peanuts","I am carrying peanuts","Peanuts are expensive"],"explain":"Alérgico/a a… names the trigger. Say it clearly before ordering food."}],"position":14},
  {"id":"french-basics","course_id":"french","title":"French Basics","theory":["French starts with music: Bonjour (hello), Merci (thank you), Au revoir (goodbye). Pronounce every syllable softly — the r rolls at the back.","Like Spanish, French nouns have gender: le for masculine, la for feminine. Fille (girl) is feminine → la fille."],"questions":[{"prompt":"\"Bonjour\" means…","correctChain":["Hello"],"scrambledTokens":["Hello","Goodbye","Thank you","Please"],"explain":"Bonjour = good day — the all-purpose French hello."},{"prompt":"\"Merci\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Sorry","Welcome","Good night"],"explain":"Merci carries you through every café in Paris."},{"prompt":"Say \"I eat apples\":","correctChain":["Je","mange","des","pommes"],"scrambledTokens":["pommes","Je","le","mange","des"],"explain":"Je = I, mange = (I) eat, des pommes = (some) apples."},{"prompt":"Which article goes with \"fille\" (girl)?","correctChain":["la"],"scrambledTokens":["la","le","les","un"],"explain":"Feminine nouns take la; masculine nouns take le."},{"prompt":"Say goodbye, friend:","correctChain":["Au","revoir","mon","ami"],"scrambledTokens":["ami","Bonjour","Au","revoir","mon"],"explain":"Au revoir = until we meet again; mon ami = my friend."}],"position":1},
  {"id":"french-phrases","course_id":"french","title":"French Phrases","theory":["Level up: ask how people are (Comment ça va?), introduce yourself (Je m’appelle…), and request politely (S’il vous plaît).","Merci scales to Merci beaucoup; Au revoir softens to À bientôt (see you soon)."],"questions":[{"prompt":"\"Comment ça va?\" means…","correctChain":["How are you?"],"scrambledTokens":["How are you?","What is your name?","Where is the station?","What time is it?"],"explain":"The classic after Bonjour."},{"prompt":"Say \"My name is Marie\":","correctChain":["Je","m'appelle","Marie"],"scrambledTokens":["Marie","Tu","Je","m'appelle"],"explain":"Je m'appelle = I call myself — the French introduction."},{"prompt":"\"S'il vous plaît\" means…","correctChain":["Please"],"scrambledTokens":["Please","Thank you","Sorry","Welcome"],"explain":"The politeness key to every French request."},{"prompt":"Say \"Thank you very much\":","correctChain":["Merci","beaucoup"],"scrambledTokens":["beaucoup","Merci","bon","très"],"explain":"Merci beaucoup — beaucoup = a lot."},{"prompt":"\"À bientôt\" means…","correctChain":["See you soon"],"scrambledTokens":["See you soon","Good night","Good luck","Welcome back"],"explain":"À = until; bientôt = soon."}],"position":2},
  {"id":"french-tenses","course_id":"french","title":"French Tenses Lab","theory":["Present tense runs on endings: -e = I/he (parle), -es = you (parles), -ons = we (parlons), -ez = you all (parlez), -ent = they (parlent, silent -nt!).","Être is the king verb — memorise it whole: je suis, tu es, il est, nous sommes, vous êtes, ils sont."],"questions":[{"prompt":"\"___ parle français.\" (I speak French.)","correctChain":["Je"],"scrambledTokens":["Je","Tu","Il","Nous"],"explain":"-e ending with no -s → Je parle."},{"prompt":"Say \"We love bread\":","correctChain":["Nous","aimons","le","pain"],"scrambledTokens":["pain","Nous","le","aimons","aimez"],"explain":"-ons = we: nous aimons."},{"prompt":"\"Tu ___ à Paris.\" (You live in Paris.)","correctChain":["habites"],"scrambledTokens":["habite","habites","habitent","habiter"],"explain":"Tu verbs take -s: tu habites."},{"prompt":"Say \"She is tired\":","correctChain":["Elle","est","fatiguée"],"scrambledTokens":["fatiguée","Elle","est","sont"],"explain":"Elle est — she is. Est also pairs with il and on."},{"prompt":"\"Ils ___ contents.\" (They are happy.)","correctChain":["sont"],"scrambledTokens":["est","sommes","sont","êtes"],"explain":"Ils + être → sont."}],"position":3},
  {"id":"french-quiz","course_id":"french","title":"French Checkpoint","theory":["Checkpoint: greetings, phrases, gender, and tenses from the full French course."],"questions":[{"prompt":"\"Bonjour\" means…","correctChain":["Hello"],"scrambledTokens":["Hello","Goodbye","Thank you","Please"],"explain":"Bonjour = good day — the all-purpose hello."},{"prompt":"Say \"I eat apples\":","correctChain":["Je","mange","des","pommes"],"scrambledTokens":["pommes","Je","le","mange","des"],"explain":"Je = I, mange = (I) eat, des pommes = (some) apples."},{"prompt":"Which article goes with \"livre\" (book)?","correctChain":["le"],"scrambledTokens":["le","la","les","des"],"explain":"Livre is masculine → le. La fille, le livre."},{"prompt":"Say \"My name is Marie\":","correctChain":["Je","m'appelle","Marie"],"scrambledTokens":["Marie","m'appelle","Je","Tu"],"explain":"Je m'appelle Marie — introduce yourself anywhere."},{"prompt":"\"Merci\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Sorry","Welcome","Good night"],"explain":"Merci carries you through every café in Paris."},{"prompt":"\"Ils ___ contents.\" (They are happy.)","correctChain":["sont"],"scrambledTokens":["est","sommes","sont","êtes"],"explain":"Tenses check: ils + être → sont."}],"position":4},
  {"id":"french-greetings","course_id":"french","title":"French Greetings & Politeness","theory":["Bonjour opens every door before evening, when Bonsoir takes over. Salut greets friends; Coucou is pure affection. Comment ça va? asks a friend, Comment allez-vous? respects an elder — tu for friends, vous for respect.","Land softly with s’il vous plaît, merci, pardon. De rien answers merci; Bienvenue welcomes all."],"questions":[{"prompt":"“Bonsoir” is said…","correctChain":["In the evening"],"scrambledTokens":["In the evening","In the morning","At noon","Only at bedtime"],"explain":"Bonjour → Bonsoir when the light fades."},{"prompt":"Ask a friend “How is it going?”:","correctChain":["Comment","ça","va"],"scrambledTokens":["va","Comment","allez","ça"],"explain":"Comment ça va? — tu form, friends and family."},{"prompt":"“Comment allez-vous?” differs from “Comment ça va?” in…","correctChain":["Formality"],"scrambledTokens":["Formality","Tense","Number","Speed"],"explain":"Vous = respect (elders, officials). Tu = friends."},{"prompt":"Answer “thanks” with “you are welcome”:","correctChain":["De","rien"],"scrambledTokens":["rien","De","Merci","Plaît"],"explain":"Merci → De rien. A tiny perfect pair."},{"prompt":"“Bienvenue!” means…","correctChain":["Welcome!"],"scrambledTokens":["Welcome!","Goodbye!","Good luck!","Congratulations!"],"explain":"Bienvenue opens every home, shop, and classroom."}],"position":5},
  {"id":"french-numbers-time","course_id":"french","title":"French Numbers & Time","theory":["Count: un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix — then the famous rebels: quatre-vingts (80, four-twenties!). Il est trois heures = it is 3 o’clock; et demie = half past, et quart = quarter past.","Days run lundi to dimanche; mois janvier to décembre. Aujourd’hui = today, demain = tomorrow, hier = yesterday."],"questions":[{"prompt":"“Huit” means…","correctChain":["Eight"],"scrambledTokens":["Eight","Seven","Nine","Eighteen"],"explain":"Sept 7, huit 8, neuf 9 — chant the run."},{"prompt":"Say “It is 3 o’clock”:","correctChain":["Il","est","trois","heures"],"scrambledTokens":["heures","Il","trois","est","sont"],"explain":"Il est + number + heures. Half past adds et demie."},{"prompt":"“Quatre-vingts” literally means…","correctChain":["Four-twenties (80)"],"scrambledTokens":["Four-twenties (80)","Four winds","Four wines","Eighty wines"],"explain":"French counts by twenties: 80 = 4×20. Glorious chaos."},{"prompt":"Say “tomorrow”:","correctChain":["Demain"],"scrambledTokens":["Hier","Demain","Aujourd’hui","Soir"],"explain":"Hier → aujourd’hui → demain: yesterday, today, tomorrow."},{"prompt":"“Et quart” after an hour means…","correctChain":["Quarter past"],"scrambledTokens":["Quarter past","Quarter to","Half past","Sharp"],"explain":"Trois heures et quart = 3:15. Moins le quart = quarter to."}],"position":6},
  {"id":"french-food","course_id":"french","title":"French Food & Drink","theory":["Order like a Parisian: Je voudrais… (I would like…), L’addition, s’il vous plaît (the bill, please). Le pain, le fromage, le café, le lait, le riz, le poulet, le poisson — hunger solved.","J’ai faim = I am hungry (I HAVE hunger), j’ai soif = I am thirsty. J’aime = I like; j’adore = I love."],"questions":[{"prompt":"“Le fromage” means…","correctChain":["The cheese"],"scrambledTokens":["The cheese","The bread","The fish","The chicken"],"explain":"Fromage = cheese, pain = bread, poisson = fish."},{"prompt":"Say “I would like coffee” politely:","correctChain":["Je","voudrais","café"],"scrambledTokens":["café","Je","voudrais","veux"],"explain":"Je voudrais = polished wanting. Je veux = blunt."},{"prompt":"“J’ai faim” literally means…","correctChain":["I have hunger"],"scrambledTokens":["I have hunger","I eat hunger","I am hunger","My hunger eats"],"explain":"French HAS hunger and thirst: j’ai faim, j’ai soif."},{"prompt":"Ask for the bill politely:","correctChain":["L’addition"],"scrambledTokens":["Le menu","L’addition","La carte","Le café"],"explain":"L’addition, s’il vous plaît — the magic exit words."},{"prompt":"“J’adore” means…","correctChain":["I love"],"scrambledTokens":["I love","I hate","I want","I need"],"explain":"J’aime = I like, j’adore = I love. J’adore le café!"}],"position":7},
  {"id":"french-travel","course_id":"french","title":"French Travel & Directions","theory":["Move with grace: Où est…? (where is…?), à gauche (left), à droite (right), tout droit (straight). La gare, l’aéroport, l’hôtel, les toilettes — the big four.","Ride anything: le bus, le train, le taxi. C’est combien? (how much?), À quelle heure part-il? (what time does it leave?)."],"questions":[{"prompt":"“Où est la gare?” asks for…","correctChain":["The station’s location"],"scrambledTokens":["The station’s location","The station’s price","Station time","A guarded room"],"explain":"Où = where. Où est…? unlocks every city."},{"prompt":"Say “to the left”:","correctChain":["À","gauche"],"scrambledTokens":["gauche","À","droite","tout"],"explain":"Gauche = left, droite = right. Tout droit = straight on."},{"prompt":"“C’est combien?” asks for…","correctChain":["The price"],"scrambledTokens":["The price","The time","The number","The name"],"explain":"Combien = how much. C’est combien? bargains anywhere."},{"prompt":"Ask where the hotel is:","correctChain":["Où","est","l’hôtel"],"scrambledTokens":["l’hôtel","Où","est","combien"],"explain":"Où est…? + place. L’hôtel, la gare, l’aéroport."},{"prompt":"“Le train” means…","correctChain":["The train"],"scrambledTokens":["The train","The bus","The taxi","The plane"],"explain":"Train = train, bus = bus, avion = plane."}],"position":8},
  {"id":"french-family","course_id":"french","title":"French Family & Descriptions","theory":["Meet la famille: la mère, le père, le frère, la sœur, le fils, la fille, l’ami. Mon/ma/mes = my, ton/ta/tes = your, son/sa/ses = his/her.","Describe with être + adjective, matching gender and number: grand/grande, petit/petite, heureux/heureuse. Je suis grand = I am tall."],"questions":[{"prompt":"“La sœur” means…","correctChain":["The sister"],"scrambledTokens":["The sister","The brother","The mother","The daughter"],"explain":"Sœur = sister, frère = brother. La famille grows."},{"prompt":"Say “my brothers” (more than one):","correctChain":["Mes","frères"],"scrambledTokens":["frères","Mon","Mes","Ton"],"explain":"Mon → mes before plurals: mes frères, mes amis."},{"prompt":"“Je suis grande” is said by…","correctChain":["A tall woman/girl"],"scrambledTokens":["A tall woman/girl","A tall man","Tall children","Anyone tall"],"explain":"Adjectives agree: grand/grande, petits/petites."},{"prompt":"Say “your (friend’s) mother”:","correctChain":["Ta","mère"],"scrambledTokens":["mère","Sa","Ta","Ma"],"explain":"Ta = your (friend), sa = his/her. Mère = mother."},{"prompt":"“Le fils” means…","correctChain":["The son"],"scrambledTokens":["The son","The daughter","The father","The thread"],"explain":"Fils = son, fille = daughter. Pronounced “feece”."}],"position":9},
  {"id":"french-verbs-present","course_id":"french","title":"French Present Verbs","theory":["Three families rule the present: -er (parler), -ir (finir), -re (vendre). Je parle, tu parles, il parle, nous parlons, ils parlent — the endings sing the person.","Must-knows: je suis (I am), j’ai (I have), je veux (I want), je peux (I can). Avoir describes age and hunger: j’ai dix ans, j’ai faim."],"questions":[{"prompt":"Say “I speak French”:","correctChain":["Je","parle","français"],"scrambledTokens":["français","Je","parles","parle"],"explain":"-er verbs: je parle (I), tu parles (you), il parle (he)."},{"prompt":"“Nous finissons” means…","correctChain":["We finish"],"scrambledTokens":["We finish","You finish","They finish","He finishes"],"explain":"-ir verbs: je finis, nous finissons, ils finissent."},{"prompt":"Say “I am happy” (être):","correctChain":["Je","suis","heureux"],"scrambledTokens":["heureux","Je","suis","es"],"explain":"Être: je suis, tu es, il est. Je suis heureux!"},{"prompt":"“Je peux” means…","correctChain":["I can"],"scrambledTokens":["I can","I want","I have","I go"],"explain":"Pouvoir → je peux. Vouloir → je veux."},{"prompt":"Say “They sell bread” (vendre):","correctChain":["Ils","vendent","pain"],"scrambledTokens":["pain","Ils","vendent","vends","vendons"],"explain":"-re verbs: je vends, ils vendent. Pain = bread."}],"position":10},
  {"id":"french-past","course_id":"french","title":"French Past Stories","theory":["Yesterday speaks in passé composé: j’ai parlé (I spoke), j’ai fini (I finished), je suis allé (I went). Most verbs take avoir; movement verbs (aller, venir, arriver) take être.","The rebels: j’ai eu (I had), j’ai fait (I did/made), j’ai dit (I said). Hier = yesterday, la semaine dernière = last week."],"questions":[{"prompt":"“J’ai parlé” means…","correctChain":["I spoke"],"scrambledTokens":["I spoke","I speak","I will speak","Speak!"],"explain":"Avoir + parlé = finished past. Je parle = now."},{"prompt":"Say “I finished” (finir):","correctChain":["J’ai","fini"],"scrambledTokens":["fini","J’ai","Je","finis"],"explain":"J’ai fini: avoir + past participle (fini)."},{"prompt":"“Je suis allé” uses être because…","correctChain":["Aller is a movement verb"],"scrambledTokens":["Aller is a movement verb","Aller is long","Allé is formal","Avoir is broken"],"explain":"DR MRS VANDERTRAMP verbs take être: aller, venir, arriver…"},{"prompt":"Say “last week”:","correctChain":["La","semaine","dernière"],"scrambledTokens":["dernière","La","semaine","hier"],"explain":"La semaine dernière frames any finished story."},{"prompt":"“J’ai fait” means…","correctChain":["I did / I made"],"scrambledTokens":["I did / I made","I do","I say","I have"],"explain":"Faire → fait. J’ai dit = I said, j’ai eu = I had."}],"position":11},
  {"id":"french-final","course_id":"french","title":"French Final Exam","theory":["Final exam: greetings, numbers, food, travel, family, present verbs, and past stories — the whole comprehensive course."],"questions":[{"prompt":"Ask a friend “How is it going?”:","correctChain":["Comment","ça","va"],"scrambledTokens":["va","Comment","allez","ça"],"explain":"Tu form for friends: Comment ça va?"},{"prompt":"“Quatre-vingts” means…","correctChain":["80"],"scrambledTokens":["80","84","20","420"],"explain":"Four-twenties: 4 × 20 = 80. Only in French!"},{"prompt":"Say “They sell bread”:","correctChain":["Ils","vendent","pain"],"scrambledTokens":["pain","Ils","vendent","vends","vendre"],"explain":"-re present: ils vendent = they sell."},{"prompt":"“J’ai faim” means…","correctChain":["I am hungry"],"scrambledTokens":["I am hungry","I have fame","I eat bread","I am thirsty"],"explain":"J’ai faim = I have hunger. J’ai soif = thirsty."},{"prompt":"“J’ai parlé” vs “je parle”: the difference is…","correctChain":["Past vs present"],"scrambledTokens":["Past vs present","Formal vs casual","Loud vs quiet","None"],"explain":"Passé composé marks the finished past: j’ai parlé = I spoke."},{"prompt":"Ask “Where is the station?”:","correctChain":["Où","est","la","gare"],"scrambledTokens":["gare","Où","est","la","combien"],"explain":"Où est…? + place. La gare = the station."},{"prompt":"You are at a boulangerie. You want two croissants and need to pay. Which is most natural?","correctChain":["Deux croissants, s’il vous plaît. Je peux payer ?"],"scrambledTokens":["Deux croissants, s’il vous plaît. Je peux payer ?","Deux croissants je payer.","Je veux deux croissants maintenant.","Croissants deux, payer oui."],"explain":"S’il vous plaît makes the order polite; “Je peux payer ?” asks to pay without demanding."},{"kind":"text","prompt":"Type the French for “I don’t understand.”","correctChain":["Je ne comprends pas."],"scrambledTokens":[],"explain":"Je ne comprends pas wraps the verb in ne … pas. In casual speech you may hear “Je comprends pas,” but the full form is the standard.","text":{"answers":["Je ne comprends pas."],"misconceptions":{"Je ne comprende pas":"Comprendre is an -re verb: the first person is je comprends, not je comprende."}}}],"position":12},
  {"id":"french-questions","course_id":"french","title":"French Questions & Negation","theory":["French asks questions three ways: rising intonation (Tu parles français ?), est-ce que (Est-ce que tu parles français ?), or inversion (Parles-tu français ?). Inversion is the most formal; est-ce que is the safest everyday form.","Question words: où (where), quand (when), pourquoi (why), comment (how), qui (who), combien (how much/many), and qu’est-ce que (what). The question word comes first: Où est la gare ?","Negation wraps the verb in ne … pas: Je ne parle pas français. In speech the ne often disappears: Je parle pas français. Other pairs: ne … jamais (never), ne … rien (nothing). Use tu with friends and vous in formal situations."],"questions":[{"prompt":"Which is the formal way to ask “Do you speak French?”","correctChain":["Parlez-vous français ?"],"scrambledTokens":["Parlez-vous français ?","Tu parles français ?","Vous parlez français.","Parles-tu français ?"],"explain":"Inversion with vous is formal: Parlez-vous…? Tu parles…? is informal; the third option is a statement."},{"prompt":"Ask “Where is the station?”","correctChain":["Où","est","la","gare"],"scrambledTokens":["gare","Où","est","la","combien"],"explain":"Où est…? + place. La gare = the station; combien asks how much."},{"prompt":"“Je ne parle pas français” means…","correctChain":["I don’t speak French"],"scrambledTokens":["I don’t speak French","I speak French","I don’t study French","I want to learn French"],"explain":"Ne … pas surrounds the verb: ne parle pas = don’t speak."},{"prompt":"Say “I don’t eat meat”:","correctChain":["Je","ne","mange","pas","de","viande"],"scrambledTokens":["viande","Je","ne","mange","pas","de","jamais"],"explain":"Je ne mange pas de viande. After a negation, de replaces the article: pas de viande."},{"prompt":"“Je ne vois rien” means…","correctChain":["I see nothing"],"scrambledTokens":["I see nothing","I don’t see the water","I see everything","I don’t want to see"],"explain":"Ne … rien is the “nothing” pair. French keeps both halves around the verb."}],"position":13},
  {"id":"french-health","course_id":"french","title":"French Health & Emergencies","theory":["Say where it hurts with avoir mal à: J’ai mal à la tête (headache), J’ai mal au ventre (stomach ache). The preposition contracts: à + le = au, à + les = aux.","Symptoms: J’ai de la fièvre (I have a fever), je tousse (I cough). Ask for help with J’ai besoin d’un médecin (I need a doctor), Où est la pharmacie ?, or Appelez une ambulance (call an ambulance — formal).","Allergies: Je suis allergique aux arachides. For polite help say Pouvez-vous m’aider ?"],"questions":[{"prompt":"“J’ai mal à la tête” means…","correctChain":["I have a headache"],"scrambledTokens":["I have a headache","I have a stomach ache","My feet hurt","I am dizzy"],"explain":"Avoir mal à + body part: la tête = the head. Au ventre is the stomach."},{"prompt":"Say “I need a doctor”:","correctChain":["J’ai","besoin","d’un","médecin"],"scrambledTokens":["médecin","J’ai","besoin","d’un","pharmacie"],"explain":"J’ai besoin de… = I need…; de + un contracts to d’un médecin."},{"prompt":"“J’ai de la fièvre” means…","correctChain":["I have a fever"],"scrambledTokens":["I have a fever","I have a cough","I am cold","I have a headache"],"explain":"Avoir de la fièvre = to have a fever. Je tousse = I cough."},{"prompt":"Ask “Where is the pharmacy?”","correctChain":["Où","est","la","pharmacie"],"scrambledTokens":["pharmacie","Où","est","la","le"],"explain":"Où est la pharmacie ? — pharmacie is feminine, so la pharmacie."},{"prompt":"“Je suis allergique aux arachides” means…","correctChain":["Peanuts make me ill"],"scrambledTokens":["Peanuts make me ill","I love peanuts","I am carrying peanuts","Peanuts are expensive"],"explain":"Allergique à… names the trigger; à + les contracts to aux."}],"position":14},
  {"id":"german-basics","course_id":"german","title":"German Basics","theory":["German starts crisp: Hallo (hello), Danke (thank you), Bitte (please/you are welcome). Every noun is capitalised — Morgen, Apfel, Frau.","German has three genders: der (masculine), die (feminine), das (neuter). Frau (woman) is feminine → die Frau."],"questions":[{"prompt":"\"Hallo\" means…","correctChain":["Hello"],"scrambledTokens":["Hello","Goodbye","Thank you","Please"],"explain":"Hallo works everywhere — shops, streets, friends."},{"prompt":"\"Danke\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Sorry","Welcome"],"explain":"Danke schön = thank you very much."},{"prompt":"Say \"I eat apples\":","correctChain":["Ich","esse","Äpfel"],"scrambledTokens":["Äpfel","Ich","der","esse"],"explain":"Ich = I, esse = (I) eat, Äpfel = apples. Note the capital Ä!"},{"prompt":"Which article goes with \"Frau\" (woman)?","correctChain":["die"],"scrambledTokens":["die","der","das","den"],"explain":"Frau is feminine → die. Der Mann, das Kind."},{"prompt":"Say \"Good morning\":","correctChain":["Guten","Morgen"],"scrambledTokens":["Morgen","Hallo","Guten","Abend"],"explain":"Guten Morgen — capital M, always."}],"position":1},
  {"id":"german-phrases","course_id":"german","title":"German Phrases","theory":["Go beyond words: ask how people are (Wie geht’s?), introduce yourself (Ich heiße…), and excuse yourself (Entschuldigung).","Danke grows to Vielen Dank; goodbyes split into formal Auf Wiedersehen and casual Tschüss."],"questions":[{"prompt":"\"Wie geht's?\" means…","correctChain":["How are you?"],"scrambledTokens":["How are you?","What is your name?","Where are you from?","What is that?"],"explain":"Short for Wie geht es dir — the casual check-in."},{"prompt":"Say \"My name is Anna\":","correctChain":["Ich","heiße","Anna"],"scrambledTokens":["Anna","Du","Ich","heiße"],"explain":"Ich heiße = I am called — the German introduction."},{"prompt":"\"Entschuldigung\" means…","correctChain":["Excuse me / Sorry"],"scrambledTokens":["Excuse me / Sorry","Thank you","Please","Welcome"],"explain":"Use it to pass by, apologise, or get attention."},{"prompt":"Say \"Thank you very much\":","correctChain":["Vielen","Dank"],"scrambledTokens":["Dank","Danke","Vielen","Bitte"],"explain":"Vielen Dank — never Danke viel!"},{"prompt":"\"Tschüss\" means…","correctChain":["Bye (informal)"],"scrambledTokens":["Bye (informal)","Good night","Good luck","Welcome back"],"explain":"Tschüss for friends; Auf Wiedersehen for formal farewells."}],"position":2},
  {"id":"german-tenses","course_id":"german","title":"German Tenses Lab","theory":["Present tense: ich takes -e (spreche), du takes -st (sprichst), er takes -t (spricht); wir/sie take the bare infinitive (lernen).","Questions flip the verb first: Bist du müde? Haben memorises as: ich habe, du hast, er hat."],"questions":[{"prompt":"\"___ spreche Deutsch.\" (I speak German.)","correctChain":["Ich"],"scrambledTokens":["Ich","Du","Er","Wir"],"explain":"-e ending → ich: ich spreche."},{"prompt":"Say \"We are learning German\":","correctChain":["Wir","lernen","Deutsch"],"scrambledTokens":["Deutsch","Wir","lernen","lernt"],"explain":"Wir + bare verb: wir lernen. No ending added!"},{"prompt":"\"Er ___ ein Auto.\" (He has a car.)","correctChain":["hat"],"scrambledTokens":["habe","hast","hat","haben"],"explain":"Haben: ich habe, du hast, er/sie/es hat."},{"prompt":"Ask \"Are you tired?\":","correctChain":["Bist","du","müde"],"scrambledTokens":["müde","du","Bist","Bin"],"explain":"Bist du = are you (informal). Verb first in questions!"},{"prompt":"\"Sie (they) ___ müde.\" (They are tired.)","correctChain":["sind"],"scrambledTokens":["bin","bist","ist","sind"],"explain":"Sein: ich bin, du bist, er ist, wir/sie sind."}],"position":3},
  {"id":"german-quiz","course_id":"german","title":"German Checkpoint","theory":["Checkpoint: greetings, phrases, gender, and tenses from the full German course."],"questions":[{"prompt":"\"Hallo\" means…","correctChain":["Hello"],"scrambledTokens":["Hello","Goodbye","Thank you","Please"],"explain":"Hallo works everywhere."},{"prompt":"Say \"I eat apples\":","correctChain":["Ich","esse","Äpfel"],"scrambledTokens":["Äpfel","Ich","der","esse"],"explain":"Ich = I, esse = (I) eat, Äpfel = apples. Capital Ä!"},{"prompt":"Which article goes with \"Mann\" (man)?","correctChain":["der"],"scrambledTokens":["der","die","das","den"],"explain":"Mann is masculine → der. Die Frau, das Kind."},{"prompt":"Say \"My name is Anna\":","correctChain":["Ich","heiße","Anna"],"scrambledTokens":["Anna","heiße","Ich","Du"],"explain":"Ich heiße Anna — introduce yourself anywhere."},{"prompt":"\"Danke\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Sorry","Welcome"],"explain":"Danke schön = thank you very much."},{"prompt":"\"Sie (they) ___ müde.\" (They are tired.)","correctChain":["sind"],"scrambledTokens":["bin","bist","ist","sind"],"explain":"Tenses check: wir/sie + sein → sind."}],"position":4},
  {"id":"german-greetings","course_id":"german","title":"German Greetings & Politeness","theory":["Hallo fits everywhere; Guten Morgen (morning), Guten Tag (day), Guten Abend (evening) ride the clock. Wie geht’s? asks a friend, Wie geht es Ihnen? respects an elder — du for friends, Sie for respect.","Always land with bitte, danke, and Entschuldigung. Gern geschehen answers danke; Willkommen welcomes all."],"questions":[{"prompt":"“Guten Abend” is said…","correctChain":["In the evening"],"scrambledTokens":["In the evening","In the morning","At noon","Only at bedtime"],"explain":"Morgen → Tag → Abend: morning, day, evening."},{"prompt":"Ask a friend “How is it going?”:","correctChain":["Wie","geht’s"],"scrambledTokens":["geht’s","Wie","geht","Ihnen"],"explain":"Wie geht’s? — du form, friends and family."},{"prompt":"“Wie geht es Ihnen?” differs from “Wie geht’s?” in…","correctChain":["Formality"],"scrambledTokens":["Formality","Tense","Number","Speed"],"explain":"Sie (capital S) = respect. du = friends."},{"prompt":"Answer “thanks” with “you are welcome”:","correctChain":["Gern","geschehen"],"scrambledTokens":["geschehen","Gern","Danke","Bitte"],"explain":"Danke → Gern geschehen. A tiny perfect pair."},{"prompt":"“Willkommen!” means…","correctChain":["Welcome!"],"scrambledTokens":["Welcome!","Goodbye!","Good luck!","Congratulations!"],"explain":"Willkommen opens every home, shop, and classroom."}],"position":5},
  {"id":"german-numbers-time","course_id":"german","title":"German Numbers & Time","theory":["Count: eins, zwei, drei, vier, fünf, sechs, sieben, acht, neun, zehn — then zwanzig, dreißig… hundert. Es ist drei Uhr = it is 3 o’clock; halb vier = half past THREE (halfway TO four!).","Days run Montag to Sonntag; Monate Januar to Dezember. Heute = today, morgen = tomorrow, gestern = yesterday."],"questions":[{"prompt":"“Sieben” means…","correctChain":["Seven"],"scrambledTokens":["Seven","Six","Eight","Seventeen"],"explain":"Sechs 6, sieben 7, acht 8 — chant the run."},{"prompt":"Say “It is 3 o’clock”:","correctChain":["Es","ist","drei","Uhr"],"scrambledTokens":["Uhr","Es","drei","ist","sind"],"explain":"Es ist + number + Uhr. Half past is halb + NEXT hour."},{"prompt":"“Halb vier” means…","correctChain":["3:30"],"scrambledTokens":["3:30","4:30","4:00","3:00"],"explain":"Halb vier = halfway to four = 3:30. Famous trap!"},{"prompt":"Say “tomorrow”:","correctChain":["Morgen"],"scrambledTokens":["Gestern","Morgen","Heute","Abend"],"explain":"Gestern → heute → morgen: yesterday, today, tomorrow."},{"prompt":"“Viertel nach drei” means…","correctChain":["Quarter past three"],"scrambledTokens":["Quarter past three","Quarter to three","Half past three","Three quarters"],"explain":"Viertel nach = quarter past; vor = to."}],"position":6},
  {"id":"german-food","course_id":"german","title":"German Food & Drink","theory":["Order like a Berliner: Ich möchte… (I would like…), Die Rechnung, bitte (the bill, please). Das Brot, der Käse, der Kaffee, die Milch, der Reis, das Hähnchen — hunger solved.","Ich habe Hunger = I am hungry (I HAVE hunger), ich habe Durst = thirsty. Ich mag = I like; ich liebe = I love. Articles matter: der/die/das!"],"questions":[{"prompt":"“Der Käse” means…","correctChain":["The cheese"],"scrambledTokens":["The cheese","The bread","The fish","The chicken"],"explain":"Käse = cheese, Brot = bread, Fisch = fish."},{"prompt":"Say “I would like coffee” politely:","correctChain":["Ich","möchte","Kaffee"],"scrambledTokens":["Kaffee","Ich","möchte","will"],"explain":"Ich möchte = polished wanting. Ich will = blunt."},{"prompt":"“Ich habe Hunger” literally means…","correctChain":["I have hunger"],"scrambledTokens":["I have hunger","I eat hunger","I am hunger","My hunger eats"],"explain":"German HAS hunger and thirst: Hunger, Durst."},{"prompt":"Ask for the bill politely:","correctChain":["Die","Rechnung"],"scrambledTokens":["Rechnung","Die","Speisekarte","Das"],"explain":"Die Rechnung, bitte — the magic exit words."},{"prompt":"“Das Hähnchen” means…","correctChain":["The chicken"],"scrambledTokens":["The chicken","The fish","The bread","The rice"],"explain":"Neuter das for Hähnchen; der for Käse. Learn noun + article!"}],"position":7},
  {"id":"german-travel","course_id":"german","title":"German Travel & Directions","theory":["Move with precision: Wo ist…? (where is…?), links (left), rechts (right), geradeaus (straight). Der Bahnhof, der Flughafen, das Hotel, die Toilette — the big four.","Ride anything: der Bus, der Zug, das Taxi. Wie viel kostet das? (how much?), Wann fährt er ab? (when does it leave?)."],"questions":[{"prompt":"“Wo ist der Bahnhof?” asks for…","correctChain":["The station’s location"],"scrambledTokens":["The station’s location","The station’s price","Station time","A farm road"],"explain":"Wo = where. Wo ist…? unlocks every city."},{"prompt":"Say “to the left”:","correctChain":["Nach","links"],"scrambledTokens":["links","Nach","rechts","geradeaus"],"explain":"Links = left, rechts = right, geradeaus = straight."},{"prompt":"“Wie viel kostet das?” asks for…","correctChain":["The price"],"scrambledTokens":["The price","The time","The weight","The name"],"explain":"Wie viel = how much. Kostet = costs."},{"prompt":"Ask where the hotel is:","correctChain":["Wo","ist","Hotel"],"scrambledTokens":["Hotel","Wo","das","ist"],"explain":"Wo ist…? + place. Das Hotel, der Bahnhof."},{"prompt":"“Der Zug” means…","correctChain":["The train"],"scrambledTokens":["The train","The bus","The taxi","The plane"],"explain":"Zug = train, Bus = bus, Flugzeug = plane."}],"position":8},
  {"id":"german-family","course_id":"german","title":"German Family & Descriptions","theory":["Meet die Familie: die Mutter, der Vater, der Bruder, die Schwester, der Sohn, die Tochter, der Freund. Mein/meine = my, dein/deine = your, sein/seine = his.","Describe with sein + adjective, matching gender and case: groß, klein, glücklich. Ich bin groß = I am tall. Capitalize every noun — always!"],"questions":[{"prompt":"“Die Schwester” means…","correctChain":["The sister"],"scrambledTokens":["The sister","The brother","The mother","The daughter"],"explain":"Schwester = sister, Bruder = brother. Die Familie grows."},{"prompt":"Say “my brothers” (more than one):","correctChain":["Meine","Brüder"],"scrambledTokens":["Brüder","Mein","Meine","Dein"],"explain":"Mein → meine before plurals/feminine: meine Brüder."},{"prompt":"“Ich bin groß” is said by…","correctChain":["A tall person"],"scrambledTokens":["A tall person","A big group","A tall building","Anyone large"],"explain":"Groß = tall/big, klein = small, glücklich = happy."},{"prompt":"Say “your (friend’s) mother”:","correctChain":["Deine","Mutter"],"scrambledTokens":["Mutter","Seine","Deine","Meine"],"explain":"Deine = your (friend), seine = his. Mutter = mother."},{"prompt":"“Der Sohn” means…","correctChain":["The son"],"scrambledTokens":["The son","The daughter","The father","The sun"],"explain":"Sohn = son, Tochter = daughter. (Die Sonne = the sun!)"}],"position":9},
  {"id":"german-verbs-present","course_id":"german","title":"German Present Verbs","theory":["Stems wear endings: sprechen (speak) → ich spreche, du sprichst, er spricht, wir sprechen, sie sprechen. Note the vowel shift e→i in du/er for strong verbs!","Must-knows: ich bin (I am), ich habe (I have), ich möchte (I want), ich kann (I can). Sein describes identity; haben holds hunger, age, time."],"questions":[{"prompt":"Say “I speak German”:","correctChain":["Ich","spreche","Deutsch"],"scrambledTokens":["Deutsch","Ich","sprichst","spreche"],"explain":"Ich spreche, du sprichst, er spricht — feel the shift."},{"prompt":"“Wir essen” means…","correctChain":["We eat"],"scrambledTokens":["We eat","You eat","They ate","He eats"],"explain":"Regular -en verbs: ich esse, wir essen, sie essen."},{"prompt":"Say “I am happy” (sein):","correctChain":["Ich","bin","glücklich"],"scrambledTokens":["glücklich","Ich","bin","bist"],"explain":"Sein: ich bin, du bist, er ist. Ich bin glücklich!"},{"prompt":"“Ich kann” means…","correctChain":["I can"],"scrambledTokens":["I can","I want","I have","I go"],"explain":"Können → ich kann. Möchten → ich möchte."},{"prompt":"Say “They sell bread” (verkaufen):","correctChain":["Sie","verkaufen","Brot"],"scrambledTokens":["Brot","Sie","verkaufen","verkauft","verkaufe"],"explain":"Regular verbs: wir/sie/Sie keep the -en: verkaufen."}],"position":10},
  {"id":"german-past","course_id":"german","title":"German Past Stories","theory":["Stories speak in Perfekt: ich habe gesprochen (I spoke), ich habe gegessen (I ate), ich bin gegangen (I went). Ge- + stem + -t/-en; movement verbs take sein.","The rebels: ich hatte (I had), ich war (I was), ich habe gemacht (I did/made). Gestern = yesterday, letzte Woche = last week."],"questions":[{"prompt":"“Ich habe gesprochen” means…","correctChain":["I spoke"],"scrambledTokens":["I spoke","I speak","I will speak","Speak!"],"explain":"Haben + gesprochen = finished past. Ich spreche = now."},{"prompt":"Say “I ate” (essen → gegessen):","correctChain":["Ich","habe","gegessen"],"scrambledTokens":["gegessen","Ich","habe","esse"],"explain":"Ge- + gess + -en: gegessen. Verb goes last!"},{"prompt":"“Ich bin gegangen” uses sein because…","correctChain":["Gehen is movement"],"scrambledTokens":["Gehen is movement","Gehen is long","Gegangen is formal","Haben is broken"],"explain":"Movement/change verbs take sein: gehen, kommen, fahren."},{"prompt":"Say “last week”:","correctChain":["Letzte","Woche"],"scrambledTokens":["Woche","Letzte","Gestern","Morgen"],"explain":"Letzte Woche frames any finished story."},{"prompt":"“Ich hatte” means…","correctChain":["I had"],"scrambledTokens":["I had","I have","I hate","I hated"],"explain":"Haben → hatte. Sein → war (ich war = I was)."}],"position":11},
  {"id":"german-final","course_id":"german","title":"German Final Exam","theory":["Final exam: greetings, numbers, food, travel, family, present verbs, and past stories — the whole comprehensive course."],"questions":[{"prompt":"Ask a friend “How is it going?”:","correctChain":["Wie","geht’s"],"scrambledTokens":["geht’s","Wie","Ihnen","geht"],"explain":"Du form for friends: Wie geht’s?"},{"prompt":"“Halb vier” means…","correctChain":["3:30"],"scrambledTokens":["3:30","4:30","4:00","Half four (4:30)"],"explain":"Halfway TO four = 3:30. The classic trap — nailed!"},{"prompt":"Say “They sell bread”:","correctChain":["Sie","verkaufen","Brot"],"scrambledTokens":["Brot","Sie","verkaufen","verkauft","verkaufe"],"explain":"Sie + -en verb: sie verkaufen = they sell."},{"prompt":"“Ich habe Hunger” means…","correctChain":["I am hungry"],"scrambledTokens":["I am hungry","I hate hunger","I eat bread","I am thirsty"],"explain":"Ich habe Hunger = I have hunger. Durst = thirst."},{"prompt":"“Ich habe gesprochen” vs “ich spreche”: the difference is…","correctChain":["Past vs present"],"scrambledTokens":["Past vs present","Formal vs casual","Loud vs quiet","None"],"explain":"Perfekt marks the finished past: habe gesprochen = spoke."},{"prompt":"Ask “Where is the station?”:","correctChain":["Wo","ist","Bahnhof"],"scrambledTokens":["Bahnhof","Wo","der","ist"],"explain":"Wo ist…? + place. Der Bahnhof = the station."},{"prompt":"At a Berlin ticket machine, you need one ticket to the city centre. Which is most natural?","correctChain":["Eine Fahrkarte ins Zentrum, bitte. Was kostet das?"],"scrambledTokens":["Eine Fahrkarte ins Zentrum, bitte. Was kostet das?","Ich Fahrkarte Zentrum.","Fahrkarte bitte billig.","Wo ist die Fahrkarte?"],"explain":"Name the ticket, add bitte, then ask Was kostet das? — the everyday polite pattern."},{"kind":"text","prompt":"Type the German for “I don’t understand.”","correctChain":["Ich verstehe nicht."],"scrambledTokens":[],"explain":"The verb goes second in a main clause: Ich verstehe nicht. Nicht follows the verb it negates.","text":{"answers":["Ich verstehe nicht."],"misconceptions":{"Ich nicht verstehe":"German keeps the verb in second position: Ich verstehe nicht."}}}],"position":12},
  {"id":"german-questions","course_id":"german","title":"German Questions & Negation","theory":["W-questions put the question word first and the verb second: Wo wohnst du? (Where do you live?), Wann kommst du? (When are you coming?), Warum lernst du Deutsch? (Why are you learning German?).","Yes/no questions start with the verb: Sprichst du Deutsch? (Do you speak German?), Hast du Zeit? (Do you have time?). The verb keeps its second position even when the subject follows it.","Negation: nicht for verbs, adjectives and definite nouns (Das ist nicht mein Buch); kein/keine for indefinite nouns (Ich habe keine Zeit, Ich spreche kein Deutsch). Use du with friends and Sie in formal situations."],"questions":[{"prompt":"Which is the correct question for “Where do you live?”","correctChain":["Wo wohnst du?"],"scrambledTokens":["Wo wohnst du?","Wo du wohnst?","Wohnst wo du?","Du wohnst wo?"],"explain":"Question word first, verb second: Wo + wohnst + du."},{"prompt":"Ask “Do you speak German?”","correctChain":["Sprichst","du","Deutsch"],"scrambledTokens":["Deutsch","Sprichst","du","sprechen"],"explain":"Yes/no question: verb first, then subject. Sprichst du Deutsch?"},{"prompt":"“Ich habe keine Zeit” means…","correctChain":["I have no time"],"scrambledTokens":["I have no time","I have lots of time","I am late","I don’t like time"],"explain":"Keine negates the indefinite noun Zeit: keine Zeit = no time."},{"prompt":"Say “I don’t speak German”:","correctChain":["Ich","spreche","kein","Deutsch"],"scrambledTokens":["Deutsch","Ich","spreche","kein","keine"],"explain":"Kein precedes the neuter noun Deutsch: kein Deutsch. Keine is for feminine/plural nouns."},{"prompt":"“Das ist nicht mein Buch” means…","correctChain":["That is not my book"],"scrambledTokens":["That is not my book","That is my book","That is no book","I don’t read that book"],"explain":"Nicht negates the definite phrase mein Buch; kein would negate an indefinite noun."}],"position":13},
  {"id":"german-health","course_id":"german","title":"German Health & Emergencies","theory":["Say what hurts with haben + a compound noun: Ich habe Kopfschmerzen (headache), Ich habe Bauchschmerzen (stomach ache). Also Ich habe Fieber (fever) and Ich huste (I cough).","Ask for help: Ich brauche einen Arzt (I need a doctor), Wo ist die Apotheke? (where is the pharmacy?), Rufen Sie einen Krankenwagen (call an ambulance — formal).","Allergies: Ich bin allergisch gegen Erdnüsse. For polite help say Können Sie mir helfen?"],"questions":[{"prompt":"“Ich habe Kopfschmerzen” means…","correctChain":["I have a headache"],"scrambledTokens":["I have a headache","I have a stomach ache","My feet hurt","I am dizzy"],"explain":"Kopf = head, Schmerzen = pain. Kopfschmerzen is the everyday headache."},{"prompt":"Say “I need a doctor”:","correctChain":["Ich","brauche","einen","Arzt"],"scrambledTokens":["Arzt","Ich","brauche","einen","Ärztin"],"explain":"Brauchen takes einen Arzt (masculine accusative); Ärztin is the female doctor."},{"prompt":"“Ich habe Fieber” means…","correctChain":["I have a fever"],"scrambledTokens":["I have a fever","I have a cough","I am cold","I have a headache"],"explain":"Fieber = fever. Ich huste = I cough."},{"prompt":"Ask “Where is the pharmacy?”","correctChain":["Wo","ist","die","Apotheke"],"scrambledTokens":["Apotheke","Wo","ist","die","der"],"explain":"Wo ist die Apotheke? — Apotheke is feminine, so die Apotheke."},{"prompt":"“Ich bin allergisch gegen Erdnüsse” means…","correctChain":["Peanuts make me ill"],"scrambledTokens":["Peanuts make me ill","I love peanuts","I am carrying peanuts","Peanuts are expensive"],"explain":"Allergisch gegen… names the trigger. Erdnüsse = peanuts."}],"position":14},
  {"id":"swahili-basics","course_id":"swahili","title":"Swahili Basics","theory":["Kiswahili is spoken by 200M+ people across East Africa. Greetings carry respect: Habari (hello/how are you), Asante (thank you), Karibu (welcome), Tafadhali (please).","Swahili verbs build like blocks: Ni-na-kula = I-am-eating. One word can be a whole sentence!"],"questions":[{"prompt":"\"Habari\" means…","correctChain":["Hello / How are you"],"scrambledTokens":["Hello / How are you","Thank you","Goodbye","Welcome"],"explain":"Habari = news — you ask for their news to say hello."},{"prompt":"\"Asante\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Sorry","Welcome"],"explain":"Asante sana = thank you very much."},{"prompt":"Say \"I am eating mangoes\":","correctChain":["Ninakula","maembe"],"scrambledTokens":["maembe","Habari","Ninakula","asante"],"explain":"Ni-na-kula = I-am-eating; maembe = mangoes."},{"prompt":"\"Karibu\" means…","correctChain":["Welcome"],"scrambledTokens":["Welcome","Goodbye","Hurry","Sorry"],"explain":"Karibu welcomes every guest — hospitality in one word."},{"prompt":"Ask \"How are you?\":","correctChain":["Habari","yako"],"scrambledTokens":["yako","Asante","Habari","karibu"],"explain":"Habari yako? = your news? — the everyday greeting."}],"position":1},
  {"id":"swahili-phrases","course_id":"swahili","title":"Swahili Phrases","theory":["Speak in sentences: introduce yourself (Jina langu ni…), greet the morning (Habari za asubuhi?), and mind your manners (Tafadhali, Asante sana).","Pole expresses sympathy (sorry about that); polepole means slowly — the most useful word pair in Swahili."],"questions":[{"prompt":"Say \"My name is Amina\":","correctChain":["Jina","langu","ni","Amina"],"scrambledTokens":["Amina","Jina","langu","ni","Wewe"],"explain":"Jina langu ni = my name is — word by word."},{"prompt":"\"Habari za asubuhi?\" means…","correctChain":["Good morning?"],"scrambledTokens":["Good morning?","Good night?","How are you?","Where are you?"],"explain":"Asubuhi = morning. Jioni = evening."},{"prompt":"Say \"Thank you very much\":","correctChain":["Asante","sana"],"scrambledTokens":["sana","Asante","ndiyo","pole"],"explain":"Sana = very. Asante sana goes a long way."},{"prompt":"\"Pole\" means…","correctChain":["Sorry"],"scrambledTokens":["Sorry","Please","Welcome","Hurry"],"explain":"Pole = sorry (sympathy). Polepole = slowly!"},{"prompt":"\"Tafadhali\" means…","correctChain":["Please"],"scrambledTokens":["Please","Thank you","Sorry","Welcome"],"explain":"Tafadhali softens every request."}],"position":2},
  {"id":"swahili-tenses","course_id":"swahili","title":"Swahili Tenses Lab","theory":["Swahili verbs wear their tense in the middle: ni-na-soma (I am reading), ni-li-soma (I read), ni-ta-soma (I will read). -na- now, -li- past, -ta- future.","The subject prefix opens every verb: ni- (I), u- (you), a- (he/she), tu- (we), wa- (they)."],"questions":[{"prompt":"Pick the present tense: “I am reading”.","correctChain":["Ninasoma"],"scrambledTokens":["Ninasoma","Nilisoma","Nitasoma","Soma"],"explain":"ni-na-soma: I + present -na- + read."},{"prompt":"Say \"They read books every day\":","correctChain":["Wanasoma","vitabu","kila","siku"],"scrambledTokens":["siku","Wanasoma","kila","vitabu","jioni"],"explain":"wa-na-soma: they + present -na- + read. Kila siku = every day."},{"prompt":"“Alipika” means he cooked — the past marker is…","correctChain":["-li-"],"scrambledTokens":["-na-","-li-","-ta-","-me-"],"explain":"-li- = past: a-li-pika. -na- is present, -ta- is future."},{"prompt":"Say \"I will come tomorrow\":","correctChain":["Nitakuja","kesho"],"scrambledTokens":["kesho","Nitakuja","Ninakuja","Nilikuja"],"explain":"ni-ta-kuja: I + future -ta- + come. Kesho = tomorrow."},{"prompt":"“Tutakula” breaks down to…","correctChain":["We will eat"],"scrambledTokens":["We will eat","We are eating","We ate","Let us eat"],"explain":"tu-ta-kula: we + future -ta- + eat."}],"position":3},
  {"id":"swahili-quiz","course_id":"swahili","title":"Swahili Checkpoint","theory":["Checkpoint: greetings, questions and negation, adjective agreement, health, verbs, and tenses from the full Swahili course."],"questions":[{"prompt":"\"Habari\" means…","correctChain":["Hello / How are you"],"scrambledTokens":["Hello / How are you","Thank you","Goodbye","Welcome"],"explain":"Habari = news — ask for their news to say hello."},{"prompt":"Say \"I am eating mangoes\":","correctChain":["Ninakula","maembe"],"scrambledTokens":["maembe","Habari","Ninakula","asante"],"explain":"Ni-na-kula = I-am-eating; maembe = mangoes."},{"prompt":"\"Karibu\" means…","correctChain":["Welcome"],"scrambledTokens":["Welcome","Goodbye","Hurry","Sorry"],"explain":"Karibu welcomes every guest."},{"prompt":"Say \"My name is Amina\":","correctChain":["Jina","langu","ni","Amina"],"scrambledTokens":["Amina","ni","Jina","langu"],"explain":"Jina langu ni Amina — introduce yourself anywhere."},{"prompt":"\"Asante\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Sorry","Welcome"],"explain":"Asante sana = thank you very much."},{"prompt":"\"Tutakula\" breaks down to…","correctChain":["We will eat"],"scrambledTokens":["We will eat","We are eating","We ate","Let us eat"],"explain":"Tenses check: tu-ta-kula = we + future -ta- + eat."},{"prompt":"“Anafanya kazi” (he works) becomes which negative?","correctChain":["Hafanyi kazi"],"scrambledTokens":["Hafanyi kazi","Hafanya kazi","Anafanya kazi","Hakufanya kazi"],"explain":"Present negative: ha- replaces a-, -na- drops, and the final -a becomes -i — hafanyi kazi."},{"prompt":"Say “good children”:","correctChain":["Watoto","wazuri"],"scrambledTokens":["wazuri","Watoto","mzuri","wadogo"],"explain":"Watoto is class 2 plural, so the adjective takes wa-: watoto wazuri. Mzuri is the singular."},{"prompt":"Tell the doctor “My head hurts”:","correctChain":["Naumwa","na","kichwa"],"scrambledTokens":["kichwa","Naumwa","na","tumbo"],"explain":"Naumwa = it hurts me; na kichwa names the place. Naumwa na tumbo is the stomach."}],"position":4},
  {"id":"swahili-greetings","course_id":"swahili","title":"Swahili Greetings & Replies","theory":["Swahili greets by time of day and by respect. Elders receive Shikamoo (I hold peace) and answer Marahaba (I accept). Peers trade Hujambo? (are you well?) and answer Sijambo (I am well). Habari za asubuhi? (morning news?) is answered Nzuri (good).","Never rush a greeting — ask twice, smile once. Follow any greeting with Uko vipi? (how are you, really?) and you sound like a local."],"questions":[{"prompt":"A young person greets an elder with “Shikamoo”. The elder replies…","correctChain":["Marahaba"],"scrambledTokens":["Marahaba","Sijambo","Nzuri","Karibu"],"explain":"Shikamoo → Marahaba. Respect offered, respect accepted."},{"prompt":"Greet a peer: “Are you well?”","correctChain":["Hujambo"],"scrambledTokens":["Sijambo","Hujambo","Marahaba","Nzuri"],"explain":"Hujambo? asks it; Sijambo answers it — a perfect pair."},{"prompt":"“Habari za asubuhi?” is the greeting for…","correctChain":["Morning"],"scrambledTokens":["Morning","Evening","Night","Midday meal"],"explain":"Asubuhi = morning. Jioni = evening, usiku = night."},{"prompt":"Answer “Habari yako?” (your news?) the short way:","correctChain":["Nzuri"],"scrambledTokens":["Mbaya","Nzuri","Pole","Tafadhali"],"explain":"Nzuri = good/fine. Short, warm, always correct."},{"prompt":"“Uko vipi?” means…","correctChain":["How are you (really)?"],"scrambledTokens":["How are you (really)?","Where are you?","Who are you?","How old are you?"],"explain":"Uko vipi deepens the greeting — ask it after Habari."}],"position":5},
  {"id":"swahili-numbers","course_id":"swahili","title":"Swahili Numbers & Money","theory":["Count to ten: moja, mbili, tatu, nne, tano, sita, saba, nane, tisa, kumi. Eleven is kumi na moja (ten and one) — the pattern never breaks, so twenty is ishirini and one hundred is mia moja.","At the market ask Bei gani? (what price?) and hear Shilingi elfu tano (five thousand shillings). Pesa = money, ghali = expensive, rahisi = cheap."],"questions":[{"prompt":"“Tatu” means…","correctChain":["Three"],"scrambledTokens":["Three","Two","Five","Ten"],"explain":"Moja 1, mbili 2, tatu 3 — chant them in order."},{"prompt":"Say “ten”:","correctChain":["Kumi"],"scrambledTokens":["Tisa","Kumi","Saba","Nane"],"explain":"Tisa 9, kumi 10. Kumi na moja = 11."},{"prompt":"“Bei gani?” asks for…","correctChain":["The price"],"scrambledTokens":["The price","The time","The place","The name"],"explain":"Bei = price. Bei gani? opens every market bargain."},{"prompt":"Say “five thousand shillings”:","correctChain":["Shilingi","elfu","tano"],"scrambledTokens":["tano","Shilingi","elfu","mia"],"explain":"Elfu = thousand: elfu tano = 5000. Mia moja = 100."},{"prompt":"The seller names a wild price. You say “Ghali!” — meaning…","correctChain":["Expensive!"],"scrambledTokens":["Expensive!","Cheap!","Free!","Sold!"],"explain":"Ghali = expensive, rahisi = cheap. Bargain with a smile."}],"position":6},
  {"id":"swahili-noun-classes","course_id":"swahili","title":"Swahili Noun Classes","theory":["Every Swahili noun belongs to a family that changes its clothes. People take m-/wa-: mtoto (child) → watoto (children). Things take ki-/vi-: kiti (chair) → viti (chairs). Adjectives must match: mtoto mdogo (small child), viti vidogo (small chairs).","Learn the pair, not the word: mti/miti (tree/trees), kitabu/vitabu (book/books). The prefix tells you singular or plural at a glance."],"questions":[{"prompt":"“Watoto” means…","correctChain":["Children"],"scrambledTokens":["Children","Child","Chairs","Books"],"explain":"Mtoto → watoto: the m-/wa- people family."},{"prompt":"Make “chairs” from kiti:","correctChain":["Viti"],"scrambledTokens":["Viti","Kiti","Ziti","Miti"],"explain":"Ki-/vi- things family: kiti → viti, kitabu → vitabu."},{"prompt":"“Mtoto mdogo” shows…","correctChain":["Adjective agreement with the noun class"],"scrambledTokens":["Adjective agreement with the noun class","Past tense","A question","A plural verb"],"explain":"Mdogo matches m-: mtoto mdogo, but viti vidogo."},{"prompt":"Say “small books” (book = kitabu):","correctChain":["Vitabu","vidogo"],"scrambledTokens":["vidogo","Kitabu","Vitabu","kidogo"],"explain":"Plural first (vitabu), then the matching adjective (vidogo)."},{"prompt":"“Miti” (trees) is the plural of…","correctChain":["Mti"],"scrambledTokens":["Mti","Mto","Mtihani","Mita"],"explain":"M-/mi- family for plants: mti → miti."}],"position":7},
  {"id":"swahili-family","course_id":"swahili","title":"Swahili Family & Possessives","theory":["Family first: mama (mother), baba (father), kaka (brother), dada (sister), mtoto (child), rafiki (friend). Possessives glue to the noun: mama yangu (my mother), baba yako (your father), kaka yake (his/her sibling).","Yangu = my, yako = your, yake = his/her, yetu = our. Jina langu ni… (my name is…) already taught you the pattern — now own it."],"questions":[{"prompt":"“Dada” means…","correctChain":["Sister"],"scrambledTokens":["Sister","Brother","Mother","Aunt"],"explain":"Dada = sister, kaka = brother. Shikamoo, dada!"},{"prompt":"Say “my mother”:","correctChain":["Mama","yangu"],"scrambledTokens":["yangu","Mama","yako","Baba"],"explain":"Mama + yangu. Swap in yako (your) or yake (his/her)."},{"prompt":"“Baba yako” means…","correctChain":["Your father"],"scrambledTokens":["Your father","My father","His father","Our father"],"explain":"Yako = your. Baba yako — ask about family with respect."},{"prompt":"Say “our friend” (friend = rafiki):","correctChain":["Rafiki","yetu"],"scrambledTokens":["yetu","Rafiki","yangu","yake"],"explain":"Yetu = our. Rafiki yetu — friendship, plural included."},{"prompt":"“Kaka yake” means…","correctChain":["His/her brother"],"scrambledTokens":["His/her brother","My brother","Your sister","Their mother"],"explain":"Yake = his/her. One word covers both — context decides."}],"position":8},
  {"id":"swahili-food-market","course_id":"swahili","title":"Swahili Food & Market","theory":["Eat your way fluent: chakula (food), wali (rice), samaki (fish), nyama (meat), matunda (fruit), maji (water), chai (tea). Hungry? Nasikia njaa (I feel hunger). Thirsty? Nasikia kiu.","At the sokoni (market): Nataka… (I want…), Kuna…? (is there…?), Bei gani? (what price?). Tafadhali and asante wrap every deal."],"questions":[{"prompt":"“Samaki” means…","correctChain":["Fish"],"scrambledTokens":["Fish","Meat","Rice","Fruit"],"explain":"Samaki = fish, nyama = meat, wali = rice."},{"prompt":"Say “I want water”:","correctChain":["Nataka","maji"],"scrambledTokens":["maji","Nataka","Chakula","Kuna"],"explain":"Nataka + anything: nataka chai, nataka matunda."},{"prompt":"“Nasikia njaa” means…","correctChain":["I am hungry"],"scrambledTokens":["I am hungry","I am thirsty","I am tired","I am full"],"explain":"Kusikia njaa = to feel hunger. Kiu = thirst."},{"prompt":"Ask “Is there rice?” at the market:","correctChain":["Kuna","wali"],"scrambledTokens":["wali","Kuna","Nataka","Bei"],"explain":"Kuna…? = is there…? Kuna samaki? Kuna matunda?"},{"prompt":"“Matunda” means…","correctChain":["Fruit"],"scrambledTokens":["Fruit","Vegetables","Spices","Bread"],"explain":"Matunda = fruit (plural). Tunda moja = one fruit."}],"position":9},
  {"id":"swahili-travel","course_id":"swahili","title":"Swahili Travel & Directions","theory":["Move like a local: Wapi? (where?), Hapa (here), Pale (there), kushoto (left), kulia (right), moja kwa moja (straight). Basi = bus, daladala = minibus, nauli = fare, tiketi = ticket.","Ask Wapi stesheni? (where is the station?) and follow Twende! (let us go!). Karibu Tanzania — safari njema (safe journey)!"],"questions":[{"prompt":"“Wapi?” means…","correctChain":["Where?"],"scrambledTokens":["Where?","When?","How?","Who?"],"explain":"Wapi = where. Wapi choo? has saved a thousand travellers."},{"prompt":"Ask “Where is the bus?”:","correctChain":["Basi","liko","wapi"],"scrambledTokens":["wapi","Basi","liko","Hapa"],"explain":"Basi liko wapi? Liko = it-is-located. Hapa = here."},{"prompt":"“Kushoto” means…","correctChain":["Left"],"scrambledTokens":["Left","Right","Straight","Back"],"explain":"Kushoto = left, kulia = right, moja kwa moja = straight."},{"prompt":"Say “Let us go!”:","correctChain":["Twende"],"scrambledTokens":["Twende","Njoo","Kaa","Rudi"],"explain":"Twende! — one word, whole journey. Safari njema!"},{"prompt":"“Nauli” is the…","correctChain":["Fare"],"scrambledTokens":["Fare","Ticket","Bus","Driver"],"explain":"Nauli = fare you pay; tiketi = the ticket itself."}],"position":10},
  {"id":"swahili-verbs-daily","course_id":"swahili","title":"Swahili Daily Verbs","theory":["Five verbs run your day: -enda (go), -ja (come), -fanya (do), -penda (like/love), -taka (want). Conjugate across people in the present: ninaenda (I go), unaenda (you go), anaenda (he/she goes), tunaenda (we go), wanaenda (they go).","Same skeleton every time: subject prefix + -na- + stem. Swap the stem, keep the rhythm — ninapenda, unataka, wanafanya."],"questions":[{"prompt":"Say “I love tea” (love = -penda):","correctChain":["Ninapenda","chai"],"scrambledTokens":["chai","Ninapenda","Unapenda","Anapenda"],"explain":"Ni-na-penda: I + present + love. Chai on the side."},{"prompt":"“Tunaenda” means…","correctChain":["We are going"],"scrambledTokens":["We are going","You are going","They are going","I am going"],"explain":"Tu- = we. Tunaenda sokoni = we are going to the market."},{"prompt":"Say “You (one person) want water”:","correctChain":["Unataka","maji"],"scrambledTokens":["maji","Unataka","Ninataka","Anataka"],"explain":"U-na-taka: you + present + want."},{"prompt":"“Wanafanya” breaks down to…","correctChain":["They are doing"],"scrambledTokens":["They are doing","We are doing","He is doing","I am doing"],"explain":"Wa-na-fanya: they + present + do."},{"prompt":"Say “She is coming” (come = -ja):","correctChain":["Anakuja"],"scrambledTokens":["Ninakuja","Anakuja","Unakuja","Tunakuja"],"explain":"A-na-kuja: she + present + come. -ja doubles the u."}],"position":11},
  {"id":"swahili-time-tense","course_id":"swahili","title":"Swahili Time & Perfect Tense","theory":["Swahili time starts at sunrise: saa moja asubuhi = 7am (hour one of the morning), saa kumi na mbili jioni = 6pm. Jana = yesterday, leo = today, kesho = tomorrow, sasa = now.","Finished actions wear -me-: nimemaliza (I have finished), umekula? (have you eaten?). -me- = done and dusted; -li- = simple past story."],"questions":[{"prompt":"“Kesho” means…","correctChain":["Tomorrow"],"scrambledTokens":["Tomorrow","Yesterday","Today","Now"],"explain":"Jana → leo → kesho: yesterday, today, tomorrow."},{"prompt":"Say “I have finished” (finish = -maliza):","correctChain":["Nimemaliza"],"scrambledTokens":["Nilimaliza","Nimemaliza","Nitamaliza","Ninamaliza"],"explain":"Ni-me-maliza: -me- marks the completed state."},{"prompt":"“Saa moja asubuhi” is…","correctChain":["7 in the morning"],"scrambledTokens":["7 in the morning","1 in the morning","12 noon","6 in the evening"],"explain":"Swahili clocks start at 6am: saa moja = 7am. Asubuhi = morning."},{"prompt":"Ask “Have you eaten?” (eat = -kula):","correctChain":["Umekula"],"scrambledTokens":["Ulikula","Umekula","Utakula","Unakula"],"explain":"U-me-kula?: -me- asks about the finished state."},{"prompt":"“Sasa” means…","correctChain":["Now"],"scrambledTokens":["Now","Later","Never","Soon"],"explain":"Sasa = now. Twende sasa! = let us go now!"}],"position":12},
  {"id":"swahili-final","course_id":"swahili","title":"Swahili Final Exam","theory":["Final exam: greetings, numbers, noun classes, family, food, travel, questions and negation, adjectives, health, verbs, and time — the whole comprehensive course."],"questions":[{"prompt":"Greet an elder respectfully and pick the reply pair:","correctChain":["Shikamoo"],"scrambledTokens":["Marahaba","Shikamoo","Sijambo","Nzuri"],"explain":"Shikamoo opens it; the elder answers Marahaba."},{"prompt":"“Vitabu vidogo” means…","correctChain":["Small books"],"scrambledTokens":["Small books","Big books","Small chairs","My books"],"explain":"Ki-/vi- agreement: vitabu + vidogo. Class match wins."},{"prompt":"Say “We are going to the market tomorrow”:","correctChain":["Tunaenda","sokoni","kesho"],"scrambledTokens":["kesho","Tunaenda","sokoni","jana"],"explain":"Tu-na-enda + sokoni (to the market) + kesho."},{"prompt":"“Umekula?” asks…","correctChain":["Have you eaten?"],"scrambledTokens":["Have you eaten?","Will you eat?","Are you eating?","Did you cook?"],"explain":"-me- perfect tense: the finished state, asked politely."},{"prompt":"“Bei gani?” + “Ghali!” means the buyer thinks it is…","correctChain":["Too expensive"],"scrambledTokens":["Too expensive","Too cheap","Free","Sold out"],"explain":"Price asked, price judged: ghali = expensive, rahisi = cheap."},{"prompt":"Say “My name is Amina, I love tea”:","correctChain":["Jina","langu","ni","Amina"],"scrambledTokens":["Amina","Jina","ni","langu"],"explain":"Introduce first: jina langu ni… — then ninapenda chai!"},{"prompt":"“Je, una pesa?” is asking…","correctChain":["Do you have money?"],"scrambledTokens":["Do you have money?","Where is the money?","How much is it?","Do you want money?"],"explain":"Je opens a yes/no question and una pesa is “you have money” — the answer is ndiyo or hapana."},{"prompt":"“Yeye ni mrefu kuliko mimi” means…","correctChain":["He is taller than me"],"scrambledTokens":["He is taller than me","He is as tall as me","I am taller than him","He is very tall"],"explain":"Kuliko = than, and mrefu takes the m- agreement of a class 1 person."},{"prompt":"Say “I have a fever”:","correctChain":["Nina","homa"],"scrambledTokens":["homa","Nina","kikohozi","dawa"],"explain":"Nina = I have; homa = fever. Kikohozi is a cough and dawa is medicine."},{"prompt":"At a market stall in Dar es Salaam, you want the price and two mangoes. Which pair is most natural?","correctChain":["Bei gani? Naomba maembe mawili."],"scrambledTokens":["Bei gani? Naomba maembe mawili.","Bei gani? Naomba maembe mbili.","Bei gani? Naomba embe mawili.","Bei gani? Nataka maembe mawili sana."],"explain":"Bei gani? asks the price; naomba is a polite request. Maembe is class 6, so the pair is mawili, not mbili."},{"kind":"text","prompt":"Type the Swahili for “I don’t understand.”","correctChain":["Sielewi."],"scrambledTokens":[],"explain":"Sielewi is the neutral “I don’t understand”; sikuelewi adds “you” — I don’t understand you. Both are useful, but sielewi is the safer default.","text":{"answers":["Sielewi.","Sikuelewi."],"misconceptions":{"Sijui":"Sijui means “I don’t know.” Use sielewi for “I don’t understand.”"}}}],"position":13},
  {"id":"swahili-questions","course_id":"swahili","title":"Swahili Questions & Negation","theory":["Open a yes/no question with Je: Je, unakwenda sokoni? (Are you going to the market?). Question words take the answer’s place: Unakwenda wapi? (Where are you going?), Unaitwa nani? (What are you called?), Kwa nini unacheka? (Why are you laughing?).","The present negative drops -na- and swaps the subject prefix: ninapenda → sipendi (I don’t like), unasoma → husomi (you don’t read), anafanya kazi → hafanyi kazi (he doesn’t work). Plural follows the same pattern: hatupendi, hampendi, hawapendi.","For possession and existence: sina (I don’t have), hatuna (we don’t have), hakuna (there is no). Keep the noun after the verb — Hakuna maji means there is no water."],"questions":[{"prompt":"Which word opens a yes/no question in Swahili?","correctChain":["Je"],"scrambledTokens":["Je","Na","Ni","Kwa"],"explain":"Je, unakwenda sokoni? — Je turns the statement into a question."},{"prompt":"Ask “Where are you going?”","correctChain":["Unakwenda","wapi"],"scrambledTokens":["wapi","Unakwenda","nani","lini"],"explain":"Unakwenda (you are going) + wapi (where). The question word closes the question."},{"prompt":"“Sipendi chai” means…","correctChain":["I don’t like tea"],"scrambledTokens":["I don’t like tea","I am drinking tea","I want tea","I don’t have tea"],"explain":"Si- is the I-negative prefix; -penda = like. Sipendi chai = I don’t like tea."},{"prompt":"Say “We don’t have money”:","correctChain":["Hatuna","pesa"],"scrambledTokens":["pesa","Hatuna","Sina","chakula"],"explain":"Hatuna = we don’t have (hatu- + na). Sina is the singular I form."},{"prompt":"“Hakuna maji” means…","correctChain":["There is no water"],"scrambledTokens":["There is no water","The water is cold","I don’t want water","Bring the water"],"explain":"Hakuna = there is no. Maji = water."}],"position":14},
  {"id":"swahili-adjectives","course_id":"swahili","title":"Swahili Adjectives & Agreement","theory":["Adjectives follow the noun and agree with its class: mtoto mzuri (a good child), watoto wazuri (good children); kitabu kizuri (a good book), vitabu vizuri (good books).","Class 9/10 nouns often take n-: nyumba nzuri (a good house), nyumba ndogo (a small house). Learn each noun with its adjective pair, not the adjective alone.","Compare with kuliko: Yeye ni mrefu kuliko mimi (He is taller than me). Common opposites: -kubwa/-dogo (big/small), -refu/-fupi (tall/short), -pya/-zee (new/old), -zuri/-baya (good/bad)."],"questions":[{"prompt":"Choose the correct pair for “a good child”:","correctChain":["mtoto mzuri"],"scrambledTokens":["mtoto mzuri","mtoto wazuri","watoto mzuri","mtoto vizuri"],"explain":"Mtoto is class 1; its adjective takes m-: mtoto mzuri. Watoto wazuri is the plural."},{"prompt":"Say “big books”:","correctChain":["Vitabu","vikubwa"],"scrambledTokens":["vikubwa","Vitabu","kubwa","vidogo"],"explain":"Vitabu is class 8 plural, so the adjective takes vi-: vitabu vikubwa."},{"prompt":"“Nyumba ndogo” means…","correctChain":["A small house"],"scrambledTokens":["A small house","A big house","A new house","Many houses"],"explain":"Nyumba is class 9/10; the adjective takes n-: ndogo = small."},{"prompt":"Say “The tree is tall”:","correctChain":["Mti","ni","mrefu"],"scrambledTokens":["mrefu","Mti","ni","fupi"],"explain":"Mti (tree) is class 3, so tall is mrefu. Ni links subject and adjective."},{"prompt":"“Kuliko” is used to…","correctChain":["Compare two things"],"scrambledTokens":["Compare two things","Mean “very”","Mark a question","Mean “and”"],"explain":"Yeye ni mrefu kuliko mimi — he is taller than me. Kuliko = than."}],"position":15},
  {"id":"swahili-health","course_id":"swahili","title":"Swahili Health & Emergencies","theory":["Naumwa means I am ill — literally “it hurts me”. Name the place with na: Naumwa na kichwa (headache), Naumwa na tumbo (stomach ache).","Nina homa (I have a fever), nina kikohozi (I have a cough). Ask for help plainly: Nisaidie! (Help me!), Nahitaji daktari (I need a doctor), Hospitali iko wapi? (Where is the hospital?).","At the pharmacy ask for dawa (medicine); in an emergency say Piga simu ya dharura (call the emergency number)."],"questions":[{"prompt":"“Naumwa na tumbo” means…","correctChain":["My stomach hurts"],"scrambledTokens":["My stomach hurts","I am hungry","I ate too much","My head hurts"],"explain":"Naumwa = it hurts me; na tumbo = in the stomach. Naumwa na kichwa is the headache."},{"prompt":"Say “I need a doctor”:","correctChain":["Nahitaji","daktari"],"scrambledTokens":["daktari","Nahitaji","dawa","hospitali"],"explain":"Nahitaji = I need; daktari = doctor. Dawa is medicine, hospitali the building."},{"prompt":"“Nisaidie!” means…","correctChain":["Help me!"],"scrambledTokens":["Help me!","I am fine","Excuse me","Goodbye"],"explain":"Nisaidie is the direct plea for help — say it loudly and clearly."},{"prompt":"Ask “Where is the hospital?”","correctChain":["Hospitali","iko","wapi"],"scrambledTokens":["wapi","Hospitali","iko","daktari"],"explain":"Hospitali iko wapi? — iko = it is (located), wapi = where."},{"prompt":"At the pharmacy you ask for…","correctChain":["dawa"],"scrambledTokens":["dawa","chakula","maji","kitabu"],"explain":"Dawa = medicine. Chakula is food, maji is water, kitabu is a book."}],"position":16},
  {"id":"swahili-politeness","course_id":"swahili","title":"Swahili Politeness & Sympathy","theory":["Swahili softens every request. Samahani (sorry / excuse me) opens one, Tafadhali (please) smooths it, and Asante (thank you) closes it. Karibu means welcome — the natural reply to Asante — and also “come in”.","Kumradhi is the formal “pardon me” heard in announcements and on phrase cards. Pole sana is sympathy, not an apology for a mistake: use it when someone is hurt or has bad news, and Samahani when you are the one who bumped, interrupted or arrived late. Hamna shida (or Hakuna shida) = no problem; Ni sawa = it’s fine."],"questions":[{"prompt":"You bump into someone in a crowd. What do you say?","correctChain":["Samahani"],"scrambledTokens":["Samahani","Asante","Karibu","Kwaheri"],"explain":"Samahani = sorry / excuse me. Asante thanks them, Karibu welcomes them, Kwaheri says goodbye."},{"prompt":"Say “Please help me”:","correctChain":["Nisaidie","tafadhali"],"scrambledTokens":["tafadhali","Nisaidie","asante","pole"],"explain":"Nisaidie = help me; tafadhali = please. Either order works — Tafadhali nisaidie is just as natural."},{"prompt":"“Asante sana” means…","correctChain":["Thank you very much"],"scrambledTokens":["Thank you very much","You are welcome","I am sorry","See you later"],"explain":"Asante = thank you; sana = very. Asante sana is the warm, everyday thank-you."},{"prompt":"Reply “You’re welcome” to Asante:","correctChain":["Karibu"],"scrambledTokens":["Karibu","Tafadhali","Pole","Kwaheri"],"explain":"Karibu is the standard reply to thanks. It also means welcome / come in."},{"prompt":"A friend tells you their grandmother died. Which reply fits?","correctChain":["Pole sana"],"scrambledTokens":["Pole sana","Tafadhali","Karibu","Asante sana"],"explain":"Pole sana expresses sympathy. Samahani would suggest you were at fault."}],"position":17},
  {"id":"swahili-introductions","course_id":"swahili","title":"Swahili Introductions & Origins","theory":["Ask a name formally with Jina lako ni nani? and casually with Unaitwaje? Answer Jina langu ni … or Ninaitwa …; Mimi ni … works in both registers.","Origin uses -toka: Umetoka wapi? (formal) / Unatoka wapi? Answer Nimetoka Kenya. Residence uses -ishi or -kaa: Unaishi wapi? / Unakaa wapi? — Naishi Nairobi. Close an introduction with Nimefurahi kukutana nawe (nice to meet you)."],"questions":[{"prompt":"Which question is the casual way to ask someone’s name?","correctChain":["Unaitwaje?"],"scrambledTokens":["Unaitwaje?","Jina lako ni nani?","Umetoka wapi?","Unaishi wapi?"],"explain":"Unaitwaje? = what are you called? Jina lako ni nani? is the formal version."},{"prompt":"Say “My name is Amina”:","correctChain":["Jina","langu","ni","Amina"],"scrambledTokens":["Amina","Jina","langu","ni","yako"],"explain":"Jina = name, langu = my, ni = is. Jina langu ni Amina. Ninaitwa Amina says the same thing."},{"prompt":"“Umetoka wapi?” asks…","correctChain":["Where are you from?"],"scrambledTokens":["Where are you from?","Where do you live?","What is your name?","How old are you?"],"explain":"-toka = come from. Answer Nimetoka Kenya (I am from Kenya). Residence uses -ishi instead."},{"prompt":"Say “I am from Kenya”:","correctChain":["Nimetoka","Kenya"],"scrambledTokens":["Nimetoka","Kenya","Naishi","Ujerumani"],"explain":"Nimetoka = I have come from / I am from. Naishi is “I live”, not “I am from”."},{"prompt":"You live in Nairobi. Best answer to “Unaishi wapi?”","correctChain":["Naishi Nairobi"],"scrambledTokens":["Naishi Nairobi","Nimetoka Nairobi","Ninaitwa Nairobi","Nimefurahi Nairobi"],"explain":"Naishi = I live. Nimetoka Nairobi would mean you come from Nairobi; the question asks where you live."}],"position":18},
  {"id":"swahili-language","course_id":"swahili","title":"Swahili Languages & Understanding","theory":["Language names wear Ki-: Kiswahili, Kiingereza (English), Kiarabu (Arabic), Kijerumani (German), Kijapani (Japanese). Ask Unazungumza Kiingereza? — in the street you will also hear Unaongea Kiingereza?","When you are lost: Sielewi (I don’t understand), Sema polepole tafadhali (speak slowly, please), Unaweza kurudia? (can you repeat?). Naelewa = I understand; Kidogo tu = just a little."],"questions":[{"prompt":"“Sielewi” means…","correctChain":["I don’t understand"],"scrambledTokens":["I don’t understand","I don’t speak","I don’t know","I don’t want it"],"explain":"Sielewi is the negative of naelewa (I understand) — the phrase for “it has not landed”."},{"prompt":"Ask “Do you speak English?” in standard Swahili:","correctChain":["Unazungumza","Kiingereza"],"scrambledTokens":["Kiingereza","Unazungumza","Unaongea","Kiarabu"],"explain":"Unazungumza = you speak; Kiingereza = English. Unaongea Kiingereza? is the common colloquial variant."},{"prompt":"You need the speaker to slow down. Which sentence do you use?","correctChain":["Sema polepole tafadhali."],"scrambledTokens":["Sema polepole tafadhali.","Sema haraka tafadhali.","Unaweza kurudia?","Naelewa."],"explain":"Polepole = slowly; sema = speak. Unaweza kurudia? asks for a repeat, not a slower pace."},{"prompt":"Say “I speak a little Swahili”:","correctChain":["Nazungumza","Kiswahili","kidogo"],"scrambledTokens":["kidogo","Nazungumza","Kiswahili","Kiingereza"],"explain":"Nazungumza = I speak; kidogo = a little. Kidogo tu adds “just a little”."},{"prompt":"“Unaweza kurudia?” asks…","correctChain":["Can you repeat?"],"scrambledTokens":["Can you repeat?","Can you help me?","Can you write it?","Can you speak English?"],"explain":"Kurudia = to repeat. Add tafadhali to keep it polite."}],"position":19},
  {"id":"swahili-money","course_id":"swahili","title":"Swahili Money & Bargaining","theory":["Ask the price with Bei gani? or Bei yake ni ngapi? (How much is it?). Ghali = expensive, rahisi = cheap; Punguza bei = lower the price. Numbers: moja … kumi, elfu = thousand, mia = hundred.","Money talk: standard Swahili is Una pesa? (do you have money?); in the market you will hear the colloquial Uko na pesa? Sina pesa = I have no money. Zimetosha = that’s enough (for things), and Bas! stops a negotiation."],"questions":[{"prompt":"“Bei yake ni ngapi?” asks…","correctChain":["How much does it cost?"],"scrambledTokens":["How much does it cost?","Where is it?","What is it?","Do you have it?"],"explain":"Bei = price, ngapi = how many / how much. Bei gani? asks the same thing."},{"prompt":"Say “It is very expensive”:","correctChain":["Ni","ghali","sana"],"scrambledTokens":["ghali","Ni","sana","rahisi"],"explain":"Ni = it is, ghali = expensive, sana = very. Rahisi is the opposite: cheap."},{"prompt":"You say “Punguza bei.” The seller understands…","correctChain":["Lower the price"],"scrambledTokens":["Lower the price","I will take it","It is cheap","No change"],"explain":"Punguza = reduce; bei = price. The friendly follow-up is “Punguza kidogo” — reduce it a little."},{"prompt":"Say “I don’t have money”:","correctChain":["Sina","pesa"],"scrambledTokens":["pesa","Sina","Nina","bei"],"explain":"Sina = I don’t have; pesa = money. Uko na pesa? is the colloquial way a seller asks if you have any."},{"prompt":"“Shilingi elfu tano” is…","correctChain":["5,000 shillings"],"scrambledTokens":["5,000 shillings","500 shillings","50 shillings","5 shillings"],"explain":"Elfu = thousand, tano = five. Shilingi elfu tano = 5,000 shillings."}],"position":20},
  {"id":"chess-basics","course_id":"chess","title":"Chess Basics","theory":["Chess is played on an 8×8 board with 16 pieces each. Every piece moves differently — knights jump in an L, bishops glide diagonally, rooks run straight, the queen does both.","The goal is checkmate: attack the enemy king so it cannot escape. Moves are written in notation — Nf3 means knight to f3, O-O means kingside castle."],"questions":[{"prompt":"How does a knight move?","correctChain":["In an L-shape: two squares one way, one sideways"],"scrambledTokens":["In an L-shape: two squares one way, one sideways","Diagonally any distance","Straight any distance","One square in any direction"],"explain":"Knights jump over pieces — the trickiest mover on the board."},{"prompt":"Which piece moves diagonally any number of squares?","correctChain":["Bishop"],"scrambledTokens":["Bishop","Rook","Knight","Pawn"],"explain":"Bishop = diagonals; rook = straights; queen = both."},{"prompt":"Knight on g1 jumps to f3. Write the move:","correctChain":["N","f3"],"scrambledTokens":["N","f3","g1","B"],"explain":"N = knight (K is the king). Then the destination square: f3."},{"prompt":"What does O-O mean in notation?","correctChain":["Kingside castle"],"scrambledTokens":["Kingside castle","Checkmate","Draw offer","Pawn promotion"],"explain":"O-O castles kingside; O-O-O castles queenside."},{"prompt":"Checkmate means…","correctChain":["The king is attacked and cannot escape — game over"],"scrambledTokens":["The king is attacked and cannot escape — game over","The king is attacked but can move","Both sides agree a draw","A pawn reaches the far rank"],"explain":"Check = attacked. Checkmate = no escape. Stalemate = draw."},{"prompt":"White pawn on e2 pushes two squares. Write it:","correctChain":["e4"],"scrambledTokens":["e4","e3","Nf3","e5"],"explain":"Pawns move straight; from rank 2 they may jump two squares."}],"position":1},
  {"id":"chess-tactics","course_id":"chess","title":"Chess Tactics","theory":["Tactics win games: a fork attacks two pieces at once, a pin freezes a piece that cannot move without exposing its king, and a discovered attack unveils a hidden attacker.","Strategy matters too: when ahead in material, trade pieces to simplify into an easy win; doubled rooks on the 7th rank feast on pawns and trap kings."],"questions":[{"prompt":"A knight attacks the king and rook at the same time. This tactic is a…","correctChain":["Fork"],"scrambledTokens":["Fork","Pin","Skewer","Discovered attack"],"explain":"One piece, two targets — the fork. Knights are fork machines."},{"prompt":"A bishop makes an enemy knight unable to move without exposing its king. This is a…","correctChain":["Pin"],"scrambledTokens":["Pin","Fork","Skewer","Castle"],"explain":"Pinned pieces are prisoners — attack what they defend."},{"prompt":"Moving a piece to unveil an attack from the piece behind it is a…","correctChain":["Discovered attack"],"scrambledTokens":["Discovered attack","Fork","Pin","Promotion"],"explain":"Two threats in one move — one of the strongest ideas in chess."},{"prompt":"When you are up a queen, trading queens is usually…","correctChain":["Good — it simplifies to an easy win"],"scrambledTokens":["Good — it simplifies to an easy win","Bad — keep the tension","Illegal","An automatic draw"],"explain":"Simplify when ahead: fewer pieces, fewer chances to blunder."},{"prompt":"Two rooks doubled on the 7th rank typically…","correctChain":["Win pawns and trap the enemy king"],"scrambledTokens":["Win pawns and trap the enemy king","Lose their power","Force a draw","Must be traded off"],"explain":"Pigs on the 7th: the most feared sight in an endgame."}],"position":2},
  {"id":"chess-quiz","course_id":"chess","title":"Chess Checkpoint","theory":["Checkpoint: piece movement, notation, tactics, and mating from the full chess course."],"questions":[{"prompt":"How does a knight move?","correctChain":["In an L-shape: two squares one way, one sideways"],"scrambledTokens":["In an L-shape: two squares one way, one sideways","Diagonally any distance","Straight any distance","One square in any direction"],"explain":"Knights jump over pieces — the trickiest mover."},{"prompt":"White pawn on e2 pushes two squares. Write it:","correctChain":["e4"],"scrambledTokens":["e4","e3","Nf3","e5"],"explain":"Pawns move straight; from rank 2 they may jump two."},{"prompt":"A pawn attacks two pieces at once. This tactic is a…","correctChain":["Fork"],"scrambledTokens":["Fork","Pin","Skewer","Castle"],"explain":"Forks work with any piece — even lowly pawns."},{"prompt":"What does O-O mean in notation?","correctChain":["Kingside castle"],"scrambledTokens":["Kingside castle","Checkmate","Draw offer","Pawn promotion"],"explain":"O-O castles kingside; O-O-O castles queenside."},{"prompt":"Checkmate means…","correctChain":["The king is attacked and cannot escape — game over"],"scrambledTokens":["The king is attacked and cannot escape — game over","The king is attacked but can move","Both sides agree a draw","A pawn reaches the far rank"],"explain":"Check = attacked. Checkmate = no escape. Stalemate = draw."}],"position":3},
  {"id":"chess-openings","course_id":"chess","title":"Chess Openings","theory":["Openings follow three laws: control the center (e4, d4, Nf3), develop knights and bishops fast, and castle early for king safety. Never move the same piece twice while others sleep.","Answer 1. e4 with 1…e5 or 1…c5; answer 1. d4 with 1…d5 or 1…Nf6. Traps punish greed — develop first, grab pawns later."],"questions":[{"prompt":"The opening’s first job is…","correctChain":["Control the center"],"scrambledTokens":["Control the center","Trade queens","Push flank pawns","Move the king up"],"explain":"Center pawns and knights first: e4, d4, Nf3, Nc3."},{"prompt":"Castle kingside in notation:","correctChain":["O-O"],"scrambledTokens":["O-O-O","O-O","0-0","Ke1"],"explain":"O-O (letter O) castles kingside; O-O-O queenside."},{"prompt":"After 1. e4, a sound Black reply is…","correctChain":["1…e5 or 1…c5"],"scrambledTokens":["1…e5 or 1…c5","1…h5","1…Na6","1…f6"],"explain":"Meet center with center or counterplay — not wing pawns."},{"prompt":"Castling early gives you…","correctChain":["A safe king + connected rooks"],"scrambledTokens":["A safe king + connected rooks","An extra queen","Two moves in a row","A draw"],"explain":"Castle by move 10 in most openings. Safety first."},{"prompt":"A knight develops toward the center. From g1 it goes to:","correctChain":["Nf3"],"scrambledTokens":["Nh3","Nf3","Ne2","Ng1"],"explain":"Nf3 attacks the center and frees castling. Nh3 sulks."}],"position":4},
  {"id":"chess-mate-patterns","course_id":"chess","title":"Checkmate Patterns","theory":["Mates repeat like songs. Back-rank mate: a rook or queen lands on the 8th rank while the king’s own pawns cage it. Scholar’s mate (Qh5/Qxf7) punishes beginners who ignore f7.","Smothered mate: a knight checks a king buried in its own pieces. Ladder mate: two rooks walk the king down the board, rank by rank."],"questions":[{"prompt":"Back-rank mate works because…","correctChain":["The king’s own pawns block its escape"],"scrambledTokens":["The king’s own pawns block its escape","The queen is pinned","Castling is illegal","The knight jumps far"],"explain":"A rook on the 8th rank + pawn wall = mate. Give luft with h3!"},{"prompt":"Scholar’s mate finishes on which square?","correctChain":["Qxf7"],"scrambledTokens":["Qxf7","Qxh5","Qxd5","Qe2"],"explain":"Qh5 then Qxf7#: f7 is weakest near the king. Defend it early!"},{"prompt":"Smothered mate is delivered by…","correctChain":["A knight"],"scrambledTokens":["A knight","A bishop","A pawn","The king"],"explain":"A knight checks a king smothered by its own pieces. Beautiful."},{"prompt":"Ladder mate uses which two pieces?","correctChain":["Rook","rook"],"scrambledTokens":["rook","Rook","queen","bishop"],"explain":"Two rooks alternate checks, pushing the king down. Rook + rook."},{"prompt":"To stop back-rank mates, you…","correctChain":["Push a luft pawn (h3/g3)"],"scrambledTokens":["Push a luft pawn (h3/g3)","Avoid castling","Trade rooks","Keep the queen home"],"explain":"Luft = breathing room. One pawn step saves the king."}],"position":5},
  {"id":"chess-endgames","course_id":"chess","title":"Essential Endgames","theory":["Few pieces, pure technique. King + queen vs king: push to the edge, keep the queen a knight’s jump away, mate on the rim. King + rook vs king: box the king with the rook, march yours up, mate.","Opposition: kings face off with one square between — whoever does NOT move holds the key. A passed pawn plus a supporting king wins; alone, it falls."],"questions":[{"prompt":"Queen vs lone king: mate happens…","correctChain":["On the edge of the board"],"scrambledTokens":["On the edge of the board","In the center","On move one","By stalemate"],"explain":"Push to the rim, queen a knight-move away, king close. Mate."},{"prompt":"The winning endgame technique is called:","correctChain":["Opposition"],"scrambledTokens":["Opposition","Forking","Pinning","Fianchetto"],"explain":"Opposition: kings one square apart — the mover loses ground."},{"prompt":"Rook vs lone king wins by…","correctChain":["Boxing the king smaller, then mating"],"scrambledTokens":["Boxing the king smaller, then mating","Sacrificing the rook","Repeating checks fast","Promoting a pawn"],"explain":"Cut the box with rook checks, walk your king up, mate."},{"prompt":"A passed pawn usually needs…","correctChain":["Its king’s support to promote"],"scrambledTokens":["Its king’s support to promote","Nothing — it always queens","A knight beside it","To move twice"],"explain":"No blockers ahead, but the king must escort it home."},{"prompt":"Stalemate means the game is a:","correctChain":["Draw"],"scrambledTokens":["Win","Draw","Loss","Replay"],"explain":"No legal moves + not in check = draw. Mate needs CHECK."}],"position":6},
  {"id":"chess-tactics-2","course_id":"chess","title":"Advanced Tactics","theory":["Beyond forks and pins: discovered attacks (move one piece, unleash another), double checks (both pieces check — the king MUST move), and deflection (drag a defender away).","Decoys lure a piece to a bad square; clearance sacrifices open a line. Ask every move: what moved, what woke up, who is undefended?"],"questions":[{"prompt":"A discovered attack happens when…","correctChain":["Moving one piece unleashes another’s attack"],"scrambledTokens":["Moving one piece unleashes another’s attack","Two knights fork","A pawn promotes","The king castles"],"explain":"Move the mask, fire the battery. Two threats, one move."},{"prompt":"Against a double check, the king must:","correctChain":["Move"],"scrambledTokens":["Move","Block","Capture","Castle"],"explain":"Two checkers — no block, no capture both. King moves!"},{"prompt":"Deflection means…","correctChain":["Dragging a defender off its duty"],"scrambledTokens":["Dragging a defender off its duty","Blocking a check","Trading queens","Losing on purpose"],"explain":"Sacrifice to pull the guard away, then strike the target."},{"prompt":"“En passant” captures…","correctChain":["A pawn that just jumped two squares"],"scrambledTokens":["A pawn that just jumped two squares","Any pawn nearby","The king","A promoted piece"],"explain":"Side pawn takes as if it moved one. Use it or lose it — immediately!"},{"prompt":"A battery lines up queen + rook on the:","correctChain":["File"],"scrambledTokens":["Rank","File","Diagonal","Square"],"explain":"Battery on a file or rank: double the pressure, double the fun."}],"position":7},
  {"id":"chess-strategy","course_id":"chess","title":"Positional Strategy","theory":["Tactics win pieces; strategy wins positions. Place knights on outposts (supported, unattackable by pawns), bishops on long diagonals, rooks on open files and the 7th rank.","Pawn structure is destiny: doubled pawns are weak, isolated pawns need guarding, passed pawns must be pushed. Trade bad bishops, keep good ones."],"questions":[{"prompt":"A knight outpost is…","correctChain":["A supported square no enemy pawn can attack"],"scrambledTokens":["A supported square no enemy pawn can attack","Any corner square","The starting square","A square with two knights"],"explain":"Outpost knights (e.g. Nd5 supported) rule whole sectors."},{"prompt":"Rooks belong…","correctChain":["On open files and the 7th rank"],"scrambledTokens":["On open files and the 7th rank","Behind pawns","In corners","On diagonals"],"explain":"Open file + 7th rank = rook heaven, feasting on pawns."},{"prompt":"A pawn with no enemies ahead of it is:","correctChain":["Passed"],"scrambledTokens":["Isolated","Passed","Doubled","Backward"],"explain":"Passed pawns must be pushed! They demand the enemy’s attention."},{"prompt":"Doubled pawns are usually…","correctChain":["Weak — hard to defend, block each other"],"scrambledTokens":["Weak — hard to defend, block each other","Strong — double power","Equal — no difference","Winning — always"],"explain":"Stacked pawns guard nothing and clog files. Avoid them."},{"prompt":"“Good bishop” means…","correctChain":["Its pawns stand on the opposite color"],"scrambledTokens":["Its pawns stand on the opposite color","It never moves","It is near the king","It takes knights"],"explain":"Pawns on light squares → dark bishop is “good”. Free the bad one!"}],"position":8},
  {"id":"chess-final","course_id":"chess","title":"Chess Final Exam","theory":["Final exam: moves, notation, openings, mating patterns, endgames, tactics, and strategy — the whole comprehensive course."],"questions":[{"prompt":"How does a knight move?","correctChain":["In an L-shape: two squares one way, one sideways"],"scrambledTokens":["In an L-shape: two squares one way, one sideways","Diagonally any distance","Straight any distance","One square any way"],"explain":"The jumper — the only piece that leaps over others."},{"prompt":"Castle kingside in notation:","correctChain":["O-O"],"scrambledTokens":["O-O-O","O-O","0-0","Kg1"],"explain":"O-O kingside, O-O-O queenside. Safety in two characters."},{"prompt":"Back-rank mate needs…","correctChain":["A rook/queen on the 8th rank + a caged king"],"scrambledTokens":["A rook/queen on the 8th rank + a caged king","Two knights","No pawns moved","Opposite castling"],"explain":"Pawn wall + last-rank invader = mate. Push luft!"},{"prompt":"Stalemate means the game is a:","correctChain":["Draw"],"scrambledTokens":["Win","Draw","Loss","Replay"],"explain":"No moves + not in check = draw. Check first, celebrate after."},{"prompt":"“J’adoube” — touch-move means…","correctChain":["A touched piece must move if legal"],"scrambledTokens":["A touched piece must move if legal","You may take back moves","Clocks pause","Draws are offered"],"explain":"Touch-move: touch it, move it. Adjust only saying “j’adoube”."},{"prompt":"Queen vs king mates on the board’s:","correctChain":["Edge"],"scrambledTokens":["Center","Edge","Corner square only","Back rank"],"explain":"Push to the rim and finish. Technique beats hope."},{"prompt":"You have a passed pawn on the seventh rank and rooks on the board. What is the strongest plan?","correctChain":["Support promotion with your rook behind the pawn."],"scrambledTokens":["Support promotion with your rook behind the pawn.","Trade rooks immediately and race the king.","Move the pawn sideways to safety.","Offer a draw before promoting."],"explain":"A passed pawn on the seventh is a winning threat: put the rook behind it, escort it, and force the defender to give way."},{"kind":"text","prompt":"Type the notation for queenside castling.","correctChain":["O-O-O"],"scrambledTokens":[],"explain":"Queenside castling is O-O-O (three symbols); kingside is O-O. Use letter O, not zero, in standard notation.","text":{"answers":["O-O-O","0-0-0"],"misconceptions":{"O-O":"O-O is kingside castling. Queenside has three symbols: O-O-O."}}}],"position":9},
  {"id":"english-basics","course_id":"english","title":"English Basics","theory":["Start with the building blocks: 26 letters, numbers, and the two little words that confuse everyone — a and an. Use an before vowel sounds (an apple), a everywhere else (a ball).","Plurals usually add -s (books), but watch the rebels: box → boxes, child → children."],"questions":[{"prompt":"How many letters are in the English alphabet?","correctChain":["26"],"scrambledTokens":["26","24","28","30"],"explain":"26 letters: A to Z. Master their sounds and spelling follows."},{"prompt":"Say the first three letters:","correctChain":["A","B","C"],"scrambledTokens":["C","A","D","B"],"explain":"A, B, C — the start of every spelling bee."},{"prompt":"Fill the gap: \"___ apple\".","correctChain":["an"],"scrambledTokens":["an","a","the","no word needed"],"explain":"An before vowel SOUNDS: an apple, an hour. A ball, a cat."},{"prompt":"The plural of \"child\" is…","correctChain":["children"],"scrambledTokens":["children","childs","childes","child"],"explain":"Irregular rebel: one child, two children. Box → boxes is regular."},{"prompt":"Say \"I am a student\":","correctChain":["I","am","a","student"],"scrambledTokens":["student","I","am","a","teacher"],"explain":"I + am + a + who you are — your first English sentence."}],"position":1},
  {"id":"english-everyday","course_id":"english","title":"Everyday English","theory":["Sound natural: introduce yourself (My name is…), ask back (Where are you from?), mind the moment (Excuse me to pass by, Sorry to apologise).","Time runs the day: What time is it? See you tomorrow. Small phrases, huge confidence."],"questions":[{"prompt":"Ask \"Where are you from?\":","correctChain":["Where","are","you","from"],"scrambledTokens":["from","Where","you","are","what"],"explain":"The friendliest question in English — memorise the order."},{"prompt":"\"What time is it?\" asks for…","correctChain":["The current time"],"scrambledTokens":["The current time","The day of the week","Your age","The date"],"explain":"Time = clock reading. Day = Monday. Date = 1st of June."},{"prompt":"You step on someone's foot. Say…","correctChain":["Sorry"],"scrambledTokens":["Sorry","Excuse me","Thank you","Welcome"],"explain":"Sorry = apologise. Excuse me = pass by or get attention."},{"prompt":"Say \"See you tomorrow\":","correctChain":["See","you","tomorrow"],"scrambledTokens":["tomorrow","See","later","you"],"explain":"See you + when: tomorrow, later, soon, on Monday."},{"prompt":"\"Nice to meet you\" is said…","correctChain":["When meeting someone for the first time"],"scrambledTokens":["When meeting someone for the first time","When leaving a party","When answering the phone","When saying thank you"],"explain":"First meeting only — then switch to \"Good to see you\"."}],"position":2},
  {"id":"english-tenses","course_id":"english","title":"English Tenses Lab","theory":["Three tenses carry 90% of conversation: present simple for habits (She goes), present continuous for right now (I am eating), past simple for finished time (I went).","Spot the -s: he/she/it verbs add -s (go → goes). Spot the clock: now/right now → am/is/are + -ing. Spot yesterday → past form."],"questions":[{"prompt":"\"She ___ to school every day.\"","correctChain":["goes"],"scrambledTokens":["goes","go","going","gone"],"explain":"He/she/it + habit → add -s: she goes, he eats."},{"prompt":"Say \"I am eating now\":","correctChain":["I","am","eating"],"scrambledTokens":["eating","I","am","was"],"explain":"am + verb-ing = happening right now."},{"prompt":"\"Yesterday I ___ to the market.\"","correctChain":["went"],"scrambledTokens":["went","go","goes","going"],"explain":"Yesterday = finished past → went (not goed!)."},{"prompt":"Say \"They will come tomorrow\":","correctChain":["They","will","come"],"scrambledTokens":["come","They","will","came"],"explain":"will + base verb = future. No -s, no -ed."},{"prompt":"\"Right now\" signals which tense?","correctChain":["Present continuous"],"scrambledTokens":["Present continuous","Present simple","Past simple","Future"],"explain":"Right now / at the moment → am/is/are + -ing."}],"position":3},
  {"id":"english-quiz","course_id":"english","title":"English Checkpoint","theory":["Checkpoint: alphabet, articles, everyday phrases, questions, describing and comparing, health, and tenses from the full English course."],"questions":[{"prompt":"Fill the gap: \"___ hour\".","correctChain":["an"],"scrambledTokens":["an","a","the","no word needed"],"explain":"Hour starts with a vowel SOUND (silent h) → an hour."},{"prompt":"Say \"I am a student\":","correctChain":["I","am","a","student"],"scrambledTokens":["student","am","I","a"],"explain":"I + am + a + who you are."},{"prompt":"\"She ___ TV every evening.\"","correctChain":["watches"],"scrambledTokens":["watches","watch","watching","watched"],"explain":"She + habit → -es after -ch: she watches."},{"prompt":"Ask \"Where are you from?\":","correctChain":["Where","are","you","from"],"scrambledTokens":["from","are","Where","you"],"explain":"Word order matters: Where + are + you + from."},{"prompt":"The plural of \"box\" is…","correctChain":["boxes"],"scrambledTokens":["boxes","boxs","boxies","box"],"explain":"After -x, add -es: box → boxes, bus → buses."},{"prompt":"Fill the gap: “___ he call you yesterday?”","correctChain":["Did"],"scrambledTokens":["Did","Does","Do","Was"],"explain":"Yesterday is past, so the auxiliary is did + base verb: did he call."},{"prompt":"The comparative of “good” is…","correctChain":["better"],"scrambledTokens":["better","gooder","more good","best"],"explain":"Good is irregular: good → better → best. “Best” is the superlative, not the comparative."},{"prompt":"Give advice: “You shouldn’t drive.”","correctChain":["You","shouldn't","drive"],"scrambledTokens":["drive","You","shouldn't","should"],"explain":"Should + not contracts to shouldn’t, then the base verb: shouldn’t drive."}],"position":4},
  {"id":"english-greetings","course_id":"english","title":"Greetings & Small Talk","theory":["Sound natural from hello: “Hi, how is it going?” beats a flat “How are you?” — answer “Pretty good, you?” and the conversation flows. “Nice to meet you” is for first meetings; “Good to see you” is for friends you already know.","Small talk runs on three topics: weather (“Lovely day, is it not?”), weekend (“Any plans?”), and the classic closer “Well, good talking to you!”"],"questions":[{"prompt":"“How is it going?” is…","correctChain":["A casual hello"],"scrambledTokens":["A casual hello","A goodbye","A complaint","A question about travel"],"explain":"Answer it like “Pretty good!” — nobody wants a medical report."},{"prompt":"Greet someone for the first time:","correctChain":["Nice","to","meet","you"],"scrambledTokens":["you","Nice","meet","to","see"],"explain":"First meeting = Nice to meet you. Later = Good to SEE you."},{"prompt":"“Any plans for the weekend?” is…","correctChain":["Friendly small talk"],"scrambledTokens":["Friendly small talk","A job interview","A complaint","A farewell"],"explain":"Weekend plans: the universal friendly filler."},{"prompt":"Close a chat warmly:","correctChain":["Good","talking","to","you"],"scrambledTokens":["you","Good","to","talking","bye"],"explain":"“Good talking to you!” ends any chat on a smile."},{"prompt":"A friend you know says hello. You reply…","correctChain":["Good to see you!"],"scrambledTokens":["Good to see you!","Nice to meet you!","Who are you?","See you never!"],"explain":"Nice to MEET you is first-time only — then it is Good to SEE you."}],"position":5},
  {"id":"english-numbers-time","course_id":"english","title":"Numbers, Time & Dates","theory":["Count with confidence: eleven to twenty are rebels (eleven, twelve, thirteen…), then the pattern locks: twenty-one, thirty-two. Hundreds and thousands stack: two hundred and five, three thousand.","Tell time two ways: “half past three” or “three thirty”; “quarter to five” or “four forty-five”. Dates flip the order: Monday the 3rd of June. At, on, in: at 5pm, on Monday, in June."],"questions":[{"prompt":"“Twelve” is the number…","correctChain":["12"],"scrambledTokens":["12","20","2","11"],"explain":"Eleven 11, twelve 12 — then thirteen adds the -teen."},{"prompt":"Say “twenty-one”:","correctChain":["twenty-one"],"scrambledTokens":["twenty-one","twelve","twenty-two","thirty-one"],"explain":"Tens + units with a hyphen: twenty-one, forty-five."},{"prompt":"“Half past three” means…","correctChain":["3:30"],"scrambledTokens":["3:30","2:30","3:15","4:30"],"explain":"Half past = 30 minutes after the hour."},{"prompt":"Say the date “Monday the 3rd of June”:","correctChain":["Monday","the","3rd"],"scrambledTokens":["3rd","Monday","June","the"],"explain":"Day first, then the + ordinal: Monday the 3rd."},{"prompt":"“___ Monday” — pick the right preposition.","correctChain":["on"],"scrambledTokens":["on","at","in","by"],"explain":"On + days, at + clock times, in + months and years."}],"position":6},
  {"id":"english-articles","course_id":"english","title":"Articles & Pointing Words","theory":["A/an introduces something new (“I saw a dog”), the points at something known (“The dog was big”). This/these stay close, that/those stand far: this book here, that shop over there.","An before vowel SOUNDS (an hour, an honest man), a elsewhere. These/those are simply the plurals of this/that."],"questions":[{"prompt":"“I saw ___ elephant.” Fill the gap.","correctChain":["an"],"scrambledTokens":["an","a","the","no word needed"],"explain":"Elephant starts with a vowel sound → an elephant."},{"prompt":"Point at a near book (one):","correctChain":["this","book"],"scrambledTokens":["book","that","this","those"],"explain":"This = near + singular. That = far + singular."},{"prompt":"“Close the door” uses “the” because…","correctChain":["Both speakers know which door"],"scrambledTokens":["Both speakers know which door","Doors are always “the”","It is the first mention","A and an are plural"],"explain":"The = shared knowledge. First mention takes a/an."},{"prompt":"Point at far shoes (many):","correctChain":["those","shoes"],"scrambledTokens":["shoes","these","those","that"],"explain":"Those = far + plural. These = near + plural."},{"prompt":"“___ honest man” — a or an?","correctChain":["an"],"scrambledTokens":["an","a","the","none"],"explain":"Honest starts with a vowel SOUND (silent h) → an honest man."}],"position":7},
  {"id":"english-food-shopping","course_id":"english","title":"Food & Shopping","theory":["Shop in English: “How much is this?” opens, “Too expensive — any discount?” bargains, “I will take it” closes. Countables take many/few (many apples), uncountables take much/little (much rice).","Soften everything with please, excuse me, and sorry. “Could I have…?” beats “Give me…” in every country on Earth."],"questions":[{"prompt":"“How much is this?” asks for…","correctChain":["The price"],"scrambledTokens":["The price","The weight","The time","The name"],"explain":"How much = price. How many = quantity."},{"prompt":"Order politely: “a coffee, please”:","correctChain":["Could","I","have"],"scrambledTokens":["have","Could","Give","I"],"explain":"“Could I have…?” — polite in every shop on Earth."},{"prompt":"“Many apples” but “much rice” because…","correctChain":["Apples are countable, rice is not"],"scrambledTokens":["Apples are countable, rice is not","Rice is plural","Apples are cheap","Much is formal"],"explain":"Many/few + countables; much/little + uncountables."},{"prompt":"Say you will buy it:","correctChain":["I","will","take","it"],"scrambledTokens":["it","I","take","will"],"explain":"“I will take it” — the deal is done. Smile included."},{"prompt":"The price shocks you. Say…","correctChain":["That is too expensive!"],"scrambledTokens":["That is too expensive!","Give it free!","Too cheap!","No money!"],"explain":"Too + adjective states the problem; then bargain."}],"position":8},
  {"id":"english-travel","course_id":"english","title":"Travel & Directions","theory":["Never get lost: “Excuse me, where is…?” opens every direction. Go straight on, turn left/right, it is on your left — then “How far is it?” and “Thank you very much!”","Book transport with “A ticket to…, please” and confirm “What time does it leave?” Single or return? Platform or gate? Ask twice, travel once."],"questions":[{"prompt":"“Turn left at the corner” means…","correctChain":["Go left when you reach the corner"],"scrambledTokens":["Go left when you reach the corner","Stop at the corner","Turn around now","Cross the road"],"explain":"Turn + direction + landmark: turn right at the bank."},{"prompt":"Ask where the station is:","correctChain":["Where","is","the","station"],"scrambledTokens":["station","Where","the","is","what"],"explain":"Where is the…? — the traveller’s master key."},{"prompt":"“It is on your right” means the place is…","correctChain":["To your right-hand side"],"scrambledTokens":["To your right-hand side","Behind you","Far away","Closed"],"explain":"On your left/right pins it to your own body."},{"prompt":"Buy a ticket politely:","correctChain":["A","ticket","to","Lagos"],"scrambledTokens":["Lagos","A","to","ticket","please"],"explain":"A ticket to + place + please. Add “return” for round trip."},{"prompt":"“What time does it leave?” asks for…","correctChain":["The departure time"],"scrambledTokens":["The departure time","The price","The platform","The arrival city"],"explain":"Leave = depart, arrive = get there. Mind both."}],"position":9},
  {"id":"english-work","course_id":"english","title":"Work & Jobs","theory":["Talk shop: “I work as a…” names the role, “I work for…” names the company, “I am responsible for…” names the duty. Can = ability (“I can code”), could = past ability or polite request (“Could you help?”).","Meetings run on three verbs: suggest (I suggest we…), agree (I agree because…), decide (We decided to…). Opinions welcome, evidence required."],"questions":[{"prompt":"“I work ___ a nurse.” Fill the gap.","correctChain":["as"],"scrambledTokens":["as","for","to","like"],"explain":"As + role, for + company: I work as a nurse for City Hospital."},{"prompt":"State an ability:","correctChain":["I","can","type"],"scrambledTokens":["type","I","could","can"],"explain":"Can + base verb: I can drive, she can cook."},{"prompt":"“Could you help me?” is…","correctChain":["A polite request"],"scrambledTokens":["A polite request","Past ability","A complaint","An order"],"explain":"Could softens requests; can states raw ability."},{"prompt":"Name a duty: “reports every Friday”:","correctChain":["responsible","for","reports"],"scrambledTokens":["reports","responsible","of","for"],"explain":"Responsible for + -ing/duty: responsible for reports."},{"prompt":"“We decided to launch” means the team…","correctChain":["Made a decision"],"scrambledTokens":["Made a decision","Had an idea","Disagreed","Delayed"],"explain":"Decide + to + verb: decided to launch, agreed to wait."}],"position":10},
  {"id":"english-past-stories","course_id":"english","title":"Past Stories","theory":["Tell what happened: past simple for finished events (I went, she bought), past continuous for the background scene (It was raining). Ago counts backwards: two days ago, a week ago.","Irregulars steal the show: go → went, eat → ate, see → saw, buy → bought. No -ed, no mercy — memorise the rebels."],"questions":[{"prompt":"“She ___ a new phone yesterday.”","correctChain":["bought"],"scrambledTokens":["bought","buy","buys","buyed"],"explain":"Buy → bought. Yesterday demands the true past form."},{"prompt":"Set the background scene:","correctChain":["It","was","raining"],"scrambledTokens":["raining","It","is","was"],"explain":"Was/were + -ing paints the background; simple past fires events."},{"prompt":"“Three days ago” means…","correctChain":["Three days before now"],"scrambledTokens":["Three days before now","In three days","For three days","Every three days"],"explain":"Ago always looks backwards from today."},{"prompt":"Say “We saw a lion”:","correctChain":["We","saw","a","lion"],"scrambledTokens":["lion","We","seed","saw","a"],"explain":"See → saw. Never “seed” — the rebels refuse -ed."},{"prompt":"“I was cooking when he arrived” — the cooking was…","correctChain":["Already in progress"],"scrambledTokens":["Already in progress","Finished first","Cancelled","Planned later"],"explain":"Past continuous = in progress; past simple = the interruption."}],"position":11},
  {"id":"english-final","course_id":"english","title":"English Final Exam","theory":["Final exam: greetings, numbers, articles, shopping, travel, work, questions, describing and comparing, health, and past stories — the whole comprehensive course."],"questions":[{"prompt":"A stranger greets you with “How is it going?” You answer…","correctChain":["Pretty good, you?"],"scrambledTokens":["Pretty good, you?","I am going home.","It goes well.","What going?"],"explain":"Casual hello → casual bounce-back. Keep it light."},{"prompt":"Point at near shoes (many):","correctChain":["these","shoes"],"scrambledTokens":["shoes","those","these","that"],"explain":"These = near + plural. Those wave from far away."},{"prompt":"“She ___ TV every evening.”","correctChain":["watches"],"scrambledTokens":["watches","watch","watching","watched"],"explain":"She + habit → -es after -ch: she watches."},{"prompt":"Ask the price politely:","correctChain":["How","much","is","this"],"scrambledTokens":["this","How","is","much"],"explain":"How much is this? — then “Could I have…?” to close."},{"prompt":"“We ___ a lion on safari.” (past)","correctChain":["saw"],"scrambledTokens":["saw","see","seed","seen"],"explain":"See → saw. The rebels never take -ed."},{"prompt":"State your job: “a driver for City Cabs”:","correctChain":["work","as","a","driver"],"scrambledTokens":["driver","work","for","as","a"],"explain":"Work AS a role, FOR a company. Both halves win."},{"prompt":"Ask about the past: “Where did he go?”","correctChain":["Where","did","he","go"],"scrambledTokens":["go","Where","did","he","went"],"explain":"After did the verb stays in the base form: did he go, never did he went."},{"prompt":"Which sentence is correct?","correctChain":["This room is more comfortable than mine."],"scrambledTokens":["This room is more comfortable than mine.","This room is comfortabler than mine.","This room is most comfortable than mine.","This room is more comfortable that mine."],"explain":"Long adjectives take more … than; -er belongs to short ones like cheaper."},{"prompt":"Say “I am allergic to peanuts”:","correctChain":["I","am","allergic","to","peanuts"],"scrambledTokens":["peanuts","I","am","allergic","to","allergy"],"explain":"I am allergic to + the food. Allergy is the noun; allergic is the adjective."},{"prompt":"You arrive at a hotel with a reservation. Which check-in line is most professional?","correctChain":["Hi, I have a reservation under Chen."],"scrambledTokens":["Hi, I have a reservation under Chen.","Give me my room, Chen.","I am Chen and I want a room now.","Reservation? Chen. Room."],"explain":"Name, reservation, and the name it is under — complete, calm, and easy for the desk to check."},{"kind":"text","prompt":"Type the past tense of the verb “buy”.","correctChain":["bought"],"scrambledTokens":[],"explain":"Buy is irregular: buy → bought. “Buyed” is never correct, even though it sounds plausible.","text":{"answers":["bought"],"misconceptions":{"buyed":"Buy is irregular: the past tense is bought, not buyed."}}}],"position":12},
  {"id":"english-questions","course_id":"english","title":"English Questions & Negatives","theory":["Present simple questions use do or does + base verb: Do you work here? Does she live in Nairobi? Past questions use did + base verb: Did they arrive?","Negatives use don’t, doesn’t or didn’t + base verb: I don’t drive. She doesn’t work here. They didn’t call. Never add -s or -ed after the auxiliary.","Question-word order is question word + auxiliary + subject + verb: Where does he live? Why did you call? Short answers repeat the auxiliary: Yes, I do. / No, she doesn’t."],"questions":[{"prompt":"“___ she live in Mombasa?”","correctChain":["Does"],"scrambledTokens":["Does","Do","Is","Did"],"explain":"She is third-person singular, so present simple takes does + live."},{"prompt":"Make it negative: “He works on Sundays.”","correctChain":["He","doesn't","work","on","Sundays"],"scrambledTokens":["He","doesn't","work","works","on","Sundays"],"explain":"The auxiliary carries the tense; work stays in the base form — doesn’t work."},{"prompt":"Choose the correct question.","correctChain":["Where does he live?"],"scrambledTokens":["Where does he live?","Where he does live?","Where does he lives?","Where do he live?"],"explain":"Question word + auxiliary + subject + base verb: where + does + he + live."},{"prompt":"Ask about the past: “Did you eat?”","correctChain":["Did","you","eat"],"scrambledTokens":["eat","Did","you","ate"],"explain":"After did, use the base verb: Did you eat? Never Did you ate?"},{"prompt":"“No, she doesn’t.” answers…","correctChain":["Does she…?"],"scrambledTokens":["Does she…?","Do she…?","Is she…?","Did she…?"],"explain":"Short answers echo the auxiliary and tense of the question — does in, doesn’t out."}],"position":13},
  {"id":"english-comparing","course_id":"english","title":"English Describing & Comparing","theory":["Adjectives go before the noun and do not take a plural -s: two big dogs, a quiet room.","Short adjectives compare with -er + than (cheaper than, taller than); longer ones use more (more expensive than). Irregulars: good → better → best, bad → worse → worst.","as … as shows equality: She is as tall as her brother. Too means more than you want; enough means sufficient: too hot, warm enough."],"questions":[{"prompt":"Which phrase is correct?","correctChain":["two big dogs"],"scrambledTokens":["two big dogs","two bigs dogs","two dogs big","two big dog"],"explain":"The adjective stays singular and sits before the noun: two big dogs."},{"prompt":"Compare: “This bag is cheaper than that one.”","correctChain":["This","bag","is","cheaper","than","that","one"],"scrambledTokens":["cheaper","This","bag","is","than","that","one","cheapest"],"explain":"One-syllable adjective + -er + than: cheaper than. Cheapest is the superlative."},{"prompt":"“More expensive” is the comparative of…","correctChain":["expensive"],"scrambledTokens":["expensive","expensiver","most expensive","expense"],"explain":"Long adjectives take more, not -er: more expensive than."},{"prompt":"Say “She is as tall as her brother.”","correctChain":["She","is","as","tall","as","her","brother"],"scrambledTokens":["tall","She","is","as","taller","as","her","brother"],"explain":"as + adjective + as shows equality; taller belongs to a than comparison."},{"prompt":"“The soup is too hot” means…","correctChain":["It is hotter than I want"],"scrambledTokens":["It is hotter than I want","It is exactly right","It is not hot","It is the hottest soup"],"explain":"Too = more than is wanted. Enough would mean it is acceptable."}],"position":14},
  {"id":"english-health","course_id":"english","title":"English Health & Emergencies","theory":["Say where it hurts with have or hurt: I have a headache. My back hurts. It hurts here. I feel dizzy.","Ask for help: I need a doctor. Could you call an ambulance? Where is the nearest pharmacy? I’m allergic to peanuts.","Give advice with should + base verb: You should rest. You shouldn’t drive. Should never takes -s or -ed."],"questions":[{"prompt":"You have a bad headache. You say…","correctChain":["I have a headache."],"scrambledTokens":["I have a headache.","I am a headache.","My headache has me.","I do a headache."],"explain":"Use have for symptoms: I have a headache / a fever / a cough."},{"prompt":"Ask for a doctor: “I need a doctor.”","correctChain":["I","need","a","doctor"],"scrambledTokens":["doctor","I","need","a","medicine"],"explain":"I need a doctor — clear, direct, and understood everywhere."},{"prompt":"“I’m allergic to peanuts” means…","correctChain":["Peanuts make me ill"],"scrambledTokens":["Peanuts make me ill","I love peanuts","I am carrying peanuts","Peanuts are expensive"],"explain":"Allergic means the body reacts badly — avoid the food and tell the staff."},{"prompt":"Give advice: “You should rest.”","correctChain":["You","should","rest"],"scrambledTokens":["rest","You","should","rested"],"explain":"Should + base verb: should rest. Never should rested or should rests."},{"prompt":"Choose the polite emergency request.","correctChain":["Could you call an ambulance?"],"scrambledTokens":["Could you call an ambulance?","Call ambulance now!","You call ambulance.","Ambulance calling?"],"explain":"Could you…? is the polite request; the emergency itself stays urgent and clear."}],"position":15}
]$catalog_lessons$::jsonb)
  as x(id text, course_id text, title text, theory jsonb, questions jsonb, position integer)
on conflict (id) do nothing;
